    // alarm-alert 弹窗样式注入（与 style.css 同步）
    (function patchAlarmAlertLayout() {
        if (document.getElementById('alarm-alert-layout-patch')) return;
        const style = document.createElement('style');
        style.id = 'alarm-alert-layout-patch';
        style.textContent = `/* 弹窗主容器：右上角定位、毛玻璃质感、默认隐藏带动画 */.alarm-alert {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 18px;
    right: 18px;
    width: min(360px, calc(100vw - 28px));
    padding: 16px;
    border-radius: 18px;
    background: linear-gradient(180deg, rgba(24, 30, 54, 0.96), rgba(20, 25, 45, 0.96));
    border: 1px solid rgba(255,255,255,0.1);
    box-shadow: 0 24px 60px rgba(0,0,0,0.34);
    backdrop-filter: blur(22px);
    z-index: 26000;
    opacity: 0;
    pointer-events: none;
    transform: translateY(-12px) scale(0.96);
    transition: 0.22s ease;
}/* 弹窗弹出状态（由 JS 控制添加此类名） */.alarm-alert.show {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0) scale(1);
}/* 标题头部区域排版 */.alarm-alert-head {
    display: grid;
    gap: 6px;
    margin-bottom: 12px;
}/* 主标题字体 */.alarm-alert-head strong {
    font-size: 15px;
    color: rgba(249, 251, 255, 0.96);
}/* 副标题与底部提示文字字体 */.alarm-alert-head span,.alarm-alert-meta {
    font-size: 12px;
    color: rgba(230, 238, 255, 0.72);
}/* 进度条轨道（背景底槽） */.alarm-alert-progress-track {
    width: 100%;
    height: 10px;
    border-radius: 999px;
    overflow: hidden;
    background: rgba(255,255,255,0.08);
    margin-bottom: 10px;
}/* 进度条填充（彩色渐变与动态收缩过渡效果） */.alarm-alert-progress-fill {
    width: 100%;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, #60a5fa, #c084fc, #f59e0b, #ef4444);
    transition: width 0.12s linear;
}/* 底部操作按钮组布局 */.alarm-alert-actions {
    display: flex;
    gap: 10px;
    margin-top: 14px;
}/* 强制操作按钮组内的按钮等宽填满 */.alarm-alert-actions > * {
    flex: 1 1 0;
}`;
        document.head.appendChild(style);
    })();
