        if (mode === 'live') return document.getElementById('bg-video');
        if (mode === 'wallhaven') return document.getElementById('bg-wallhaven-img');
        if (mode === 'unsplash') return document.getElementById('bg-unsplash-img');
        if (mode === 'picsum') return document.getElementById('bg-picsum-img');
        if (mode === 'wpupx8') return document.getElementById('bg-wpupx8-img');
