    function deleteAlarmSound(alarmId) {
        if (alarmId === DEFAULT_ALARM_ID) {
            showToast('默认提醒音不能删除');
            return;
        }
        const removed = state.alarmSounds.find(item => item.id === alarmId);
        if (removed && removed.source === 'local_db') {
            deleteMediaFromDB(removed.id);
            URL.revokeObjectURL(removed.src);
        }
        state.alarmSounds = state.alarmSounds.filter(item => item.id !== alarmId);
        if (state.selectedAlarmSoundId === alarmId) state.selectedAlarmSoundId = DEFAULT_ALARM_ID;
        saveAlarmLibrary();
        renderAlarmSoundOptions();
        updateAlarmStatus();
        renderAlarmSoundList();
        showToast('铃声已删除');
    }
    window.deleteAlarmSound = deleteAlarmSound;
