    function renderTodoBoards(focusBoardId = '') {
        if (!todoBoardList) return;
        state.todoBoards = getSortedTodoBoards();
        const formatDisplayDate = (dateStr) => {
            if (!dateStr) return '时间';
            if (!state.use12HourFormat) return dateStr.slice(5, 16);
            const [d, t] = dateStr.split(' ');
            if (!t) return dateStr.slice(5);
            const [h, m] = t.split(':');
            let hNum = parseInt(h, 10);
            const ampm = hNum >= 12 ? '下午' : '上午';
            hNum = hNum % 12 || 12;
            return `${d.slice(5)} ${ampm}${String(hNum).padStart(2, '0')}:${m}`;
        };
        // ===================================
        // 📅 日历视图与通用组件绑定
        // ===================================
        const bindTodoGeneralEvents = () => {
            todoBoardList.querySelectorAll('[data-todo-view]').forEach(btn => {
                btn.onclick = () => {
                    state.todoViewMode = btn.dataset.todoView;
                    localStorage.setItem('todo_view_mode', state.todoViewMode);
                    renderTodoBoards();
                };
            });
            const exportBtn = document.getElementById('export-ics-btn');
            if (exportBtn) {
                exportBtn.onclick = () => {
                    let icsContent = "BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//BinixOvO//TabPro//EN\n";
                    let hasEvent = false;
                    const parseDateTimeToICS = (dtStr) => {
                        if (!dtStr) return '';
                        const [d, t] = dtStr.split(' ');
                        if (!d || !t) return '';
                        return `${d.replace(/-/g, '')}T${t.replace(/:/g, '')}00`;
                    };
                    state.todoBoards.forEach(board => {
                        if (board.dueDate && !board.completed) {
                            hasEvent = true;
                            icsContent += "BEGIN:VEVENT\n";
                            icsContent += `UID:${board.id}@binix.tab\n`;
                            icsContent += `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').split('.')[0]}Z\n`;
                            icsContent += `DTSTART:${parseDateTimeToICS(board.dueDate)}\n`;
                            icsContent += "BEGIN:VALARM\nACTION:DISPLAY\nDESCRIPTION:REMINDER\nTRIGGER:-PT10M\nEND:VALARM\n";
                            icsContent += `SUMMARY:【表截止】${board.name}\n`;
                            icsContent += "END:VEVENT\n";
                        }
                    });
                    icsContent += "END:VCALENDAR";
                    if (!hasEvent) {
                        alert('当前没有设置了截止日期的未完成任务！');
                        return;
                    }
                    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
                    const url = URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = "BinixTab_Todo.ics";
                    document.body.appendChild(a);
                    a.click();
                    document.body.removeChild(a);
                    URL.revokeObjectURL(url);
                    if (typeof showToast === 'function') showToast('已生成系统日历订阅文件 (.ics)');
                };
            }
            todoBoardList.querySelectorAll('[data-toggle-item]').forEach(btn => {
                const [boardId, itemId] = btn.dataset.toggleItem.split(':');
                btn.onclick = (e) => {
                    if (itemId === 'board_only') toggleTodoBoard(boardId);
                    else toggleTodoItem(boardId, itemId, e);
                };
            });
        };
        // ===================================
        // 📊 实时全局任务统计与饼图生成 (按表计算)
        // ===================================
        let totalBoards = state.todoBoards.length;
        let completedBoards = state.todoBoards.filter(b => b.completed).length;
        const percent = totalBoards === 0 ? 0 : Math.round((completedBoards / totalBoards) * 100);
        const statsHtml = `
            <div class="todo-stats">
                <div class="todo-pie" style="--percent: ${percent};"></div>
                <div class="todo-stats-info">
                    <div class="todo-stats-title">当前代办表完成进度：${percent}%</div>
                    <div class="todo-stats-desc">${completedBoards} 表已完成 / 共 ${totalBoards} 表</div>
                </div>
            </div>
        `;
        if (state.todoViewMode === 'calendar') {
            const now = state.currentCalMonth || new Date();
            const year = now.getFullYear();
            const month = now.getMonth();
            const firstDay = new Date(year, month, 1);
            const lastDay = new Date(year, month + 1, 0);
            const startDayOfWeek = firstDay.getDay();
            const daysInMonth = lastDay.getDate();
            const tasksByDate = {};
            state.todoBoards.forEach(board => {
                if (board.dueDate) {
                    const dateOnly = board.dueDate.split(' ')[0];
                    if (!tasksByDate[dateOnly]) tasksByDate[dateOnly] = [];
                    const pendingCount = board.items ? board.items.filter(i => !i.completed).length : 0;
                    tasksByDate[dateOnly].push({ text: board.name, completed: board.completed, boardId: board.id, id: 'board_only', color: board.color || '#a5b4fc', pendingCount });
                }
            });
            let html = `
                <div class="todo-view-toggle">
                    <button class="ui-button small-btn" style="flex:1" data-todo-view="list">📋 列表</button>
                    <button class="ui-button small-btn" style="flex:1; background: var(--text-b); color: #000; font-weight: bold; border: none;" data-todo-view="calendar">📅 日历</button>
                    <button class="ui-button small-btn" style="flex:1" id="export-ics-btn" title="导出日历订阅文件导入到系统日历">⬇️ 同步日历</button>
                </div>
                ${statsHtml}
                <div class="calendar-view">
                    <div class="calendar-header">
                        <button class="ui-button small-btn" style="width: auto" id="cal-prev-month">◀</button>
                        <span>${year}年 ${month + 1}月</span>
                        <button class="ui-button small-btn" style="width: auto" id="cal-next-month">▶</button>
                    </div>
                    <div class="calendar-grid">
                        ${['日','一','二','三','四','五','六'].map((d, idx) => `<div class="calendar-day-header ${idx === 0 || idx === 6 ? 'weekend' : ''}">${d}</div>`).join('')}
            `;
            for (let i = 0; i < startDayOfWeek; i++) { html += `<div class="calendar-cell ${i === 0 || i === 6 ? 'weekend' : ''}" style="opacity: 0.1"></div>`; }
            const todayStr = new Date().toISOString().split('T')[0];
            for (let i = 1; i <= daysInMonth; i++) {
                const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
                const isToday = dateStr === todayStr;
                const isWeekend = (startDayOfWeek + i - 1) % 7 === 0 || (startDayOfWeek + i - 1) % 7 === 6;
                const tasks = tasksByDate[dateStr] || [];
                let tasksHtml = tasks.map(t => {
                    const badgeHtml = t.pendingCount > 0 ? `<span class="calendar-task-badge">${t.pendingCount}</span>` : '';
                    return `<div class="calendar-task ${t.completed ? 'completed' : ''}" title="${t.text}" data-toggle-item="${t.boardId}:${t.id}" style="border-left-color: ${t.color}; background-color: color-mix(in srgb, ${t.color} 25%, rgba(255,255,255,0.03));"><span class="calendar-task-title">${t.text}</span>${badgeHtml}</div>`;
                }).join('');
                html += `<div class="calendar-cell ${isToday ? 'today' : ''} ${isWeekend ? 'weekend' : ''}"><div class="calendar-date-num">${i}</div>${tasksHtml}</div>`;
            }
            todoBoardList.innerHTML = html + `</div></div>`;
            bindTodoGeneralEvents();
            document.getElementById('cal-prev-month').onclick = () => { state.currentCalMonth = new Date(year, month - 1, 1); renderTodoBoards(); };
            document.getElementById('cal-next-month').onclick = () => { state.currentCalMonth = new Date(year, month + 1, 1); renderTodoBoards(); };
            return;
        }
        const viewToggleHtml = `
            <div class="todo-view-toggle">
                <button class="ui-button small-btn" style="flex:1; background: color-mix(in srgb, var(--text-b) 80%, #000); color: #000; border: none; font-weight: bold;" data-todo-view="list">📋 列表</button>
                <button class="ui-button small-btn" style="flex:1" data-todo-view="calendar">📅 日历</button>
                <button class="ui-button small-btn" style="flex:1" id="export-ics-btn" title="导出日历订阅文件导入到系统日历">⬇️ 同步日历</button>
            </div>
            ${statsHtml}
        `;
        const boardsHtml = state.todoBoards.map(board => {
            const items = getSortedTodoItems(board.items || []);
            const checked = board.completed ? ' checked' : '';
            const boardDone = board.completed ? ' completed' : '';
            const collapsed = isTodoBoardCollapsed(board.id);
            const pendingCount = items.filter(item => !item.completed).length;
            const meta = pendingCount > 0 ? `${pendingCount}` : '';
            const boardIcon = board.icon || '📋';
            const boardColor = board.color || '#a5b4fc';
            const boardOpacity = (board.opacity ?? 100) / 100;
            const boardNote = board.note || '';
            const noteSuffix = boardNote ? `（${boardNote}）` : '';
            return `
                <section class="todo-board${boardDone}${collapsed ? ' collapsed' : ''}" data-board-id="${board.id}" style="--board-color:${boardColor}; opacity:${boardOpacity};">
                    <div class="todo-board-head">
                        <button type="button" class="todo-check${checked}" data-toggle-board="${board.id}"><span>√</span></button>
                        <input type="color" class="todo-board-color" data-board-color="${board.id}" title="设置颜色标签" value="${boardColor}">
                        <button type="button" class="todo-board-main" data-toggle-collapse="${board.id}">
                            <div class="todo-board-title-wrap">
                                <span class="todo-board-icon">${boardIcon}</span>
                                <span class="todo-board-title" data-rename-board="${board.id}" title="双击重命名">${escapeHTML(board.name)}${noteSuffix}</span>
                                <span class="todo-board-meta">${meta}</span>
                            </div>
                        </button>
                    <button type="button" class="todo-date-btn" data-set-date-board="${board.id}" title="设置截止时间" style="margin-left:0; margin-right:6px;">📅 ${formatDisplayDate(board.dueDate)}</button>
                        <button type="button" class="todo-collapse-btn" data-toggle-collapse="${board.id}" title="折叠或展开"></button>
                        <button type="button" class="todo-board-handle" title="拖动表">☰</button>
                    </div>
                    <div class="todo-board-body">
                        <div class="todo-add-row">
                            <input type="text" class="ui-input compact-input todo-inline-input" data-todo-input="${board.id}" placeholder="添加项目">
                            <button class="ui-button small-btn todo-inline-btn" data-add-item="${board.id}">新增</button>
                        </div>
                        <div class="todo-item-list" data-item-list="${board.id}">
                            ${items.length ? items.map(item => `
                                <div class="todo-item${item.completed ? ' completed' : ''}" data-item-id="${item.id}">
                                    <button type="button" class="todo-check${item.completed ? ' checked' : ''}" data-toggle-item="${board.id}:${item.id}"><span>√</span></button>
                                    <button type="button" class="todo-item-handle" title="拖动项目">⋮⋮</button>
                                    <span class="todo-item-text">${escapeHTML(item.text)}</span>
                            <button type="button" class="todo-date-btn" data-set-date="${board.id}:${item.id}" title="设置截止时间">📅 ${formatDisplayDate(item.dueDate)}</button>
                                </div>
                            `).join('') : `<div class="todo-empty-state">还没有项目，直接勾选表也可以结束。</div>`}
                        </div>
                    </div>
                </section>
            `;
        }).join('');
        todoBoardList.innerHTML = viewToggleHtml + boardsHtml;
        bindTodoGeneralEvents();
        todoBoardList.querySelectorAll('[data-toggle-board]').forEach(btn => {
            btn.onclick = () => toggleTodoBoard(btn.dataset.toggleBoard);
        });
        todoBoardList.querySelectorAll('[data-toggle-collapse]').forEach(btn => {
            btn.onclick = () => toggleTodoBoardCollapsed(btn.dataset.toggleCollapse);
        });
        todoBoardList.querySelectorAll('[data-rename-board]').forEach(label => {
            label.ondblclick = (e) => {
                e.stopPropagation();
                renameTodoBoard(label.dataset.renameBoard);
            };
        });
        todoBoardList.querySelectorAll('[data-add-item]').forEach(btn => {
            btn.onclick = () => {
                const input = todoBoardList.querySelector(`[data-todo-input="${btn.dataset.addItem}"]`);
                if (!input) return;
                addTodoItem(btn.dataset.addItem, input.value);
            };
        });
        todoBoardList.querySelectorAll('[data-todo-input]').forEach(input => {
            input.onkeydown = (e) => {
                if (e.key === 'Enter') addTodoItem(input.dataset.todoInput, input.value);
            };
        });
        todoBoardList.querySelectorAll('[data-set-date-board]').forEach(btn => {
            btn.onclick = (e) => {
                e.stopPropagation();
                const boardId = btn.dataset.setDateBoard;
                const board = state.todoBoards.find(item => item.id === boardId);
                if (board && typeof window.openTodoDateModal === 'function') {
                    window.openTodoDateModal('board', boardId, null, board.dueDate);
                }
            };
        });
        todoBoardList.querySelectorAll('[data-set-date]').forEach(btn => {
            btn.onclick = (e) => {
                const [boardId, itemId] = btn.dataset.setDate.split(':');
                const board = state.todoBoards.find(item => item.id === boardId);
                const todo = board?.items.find(item => item.id === itemId);
                if (todo && typeof window.openTodoDateModal === 'function') {
                    window.openTodoDateModal('item', boardId, itemId, todo.dueDate);
                }
            };
        });
        todoBoardList.querySelectorAll('[data-board-color]').forEach(input => {
            input.onchange = (e) => {
                const boardId = e.target.dataset.boardColor;
                const board = state.todoBoards.find(item => item.id === boardId);
                if (board) {
                    board.color = e.target.value;
                    saveTodoBoards();
                    renderTodoBoards();
                }
            };
        });
        todoBoardList.querySelectorAll('.todo-board-head').forEach(head => {
            head.oncontextmenu = (e) => {
                e.preventDefault();
                const boardEl = head.closest('.todo-board');
                const boardId = boardEl.dataset.boardId;
                const board = state.todoBoards.find(b => b.id === boardId);
                if (!board) return;
                board.icon = board.icon || '📋';
                board.color = board.color || '#a5b4fc';
                board.opacity = board.opacity ?? 100;
                board.note = board.note || '';
                showBoardContextMenu(e.clientX, e.clientY, board);
            };
        });
        initTodoSortables();
        if (focusBoardId) {
            const input = todoBoardList.querySelector(`[data-todo-input="${focusBoardId}"]`);
            if (input) {
                requestAnimationFrame(() => {
                    input.focus();
                    input.select();
                });
            }
        }
    }
    function showBoardContextMenu(x, y, board) {
        const existing = document.querySelector('.board-context-menu');
        if (existing) existing.remove();
        const icons = [
            '📋','📝','📌','📎','📁','📂','🗂️','📊','📈','📉',
            '⭐','🌟','✨','💡','🔥','💎','🎯','🏆','📦','🗃️',
            '📅','📆','⏰','⌛','🔔','📢','💬','📧','📨','📩',
            '⚡','🎵','🎶','🎨','🌈','☀️','🌙','⭐','🌊','🍀',
            '🎪','🎭','🎬','🏠','🚀','✈️','💻','📱','🎮','🎲',
            '🔧','🔨','⚙️','🔑','💊','🧩','📯','🛡️','🏷️','📛'
        ];
        const menu = document.createElement('div');
        menu.className = 'board-context-menu';
        menu.style.cssText = `position:fixed;left:${x}px;top:${y}px;z-index:30000;`;
        menu.innerHTML = `
            <div class="bcm-section">
                <div class="bcm-label">图标</div>
                <div class="bcm-icon-grid">
                    ${icons.map(icon => `<button class="bcm-icon-btn${board.icon === icon ? ' active' : ''}" data-icon="${icon}">${icon}</button>`).join('')}
                </div>
            </div>
            <div class="bcm-section">
                <div class="bcm-label">颜色</div>
                <input type="color" class="bcm-color-input" value="${board.color}">
            </div>
            <div class="bcm-section">
                <div class="bcm-label">透明度 <span class="bcm-op-val">${board.opacity}%</span></div>
                <input type="range" class="bcm-opacity-slider" min="20" max="100" value="${board.opacity}">
            </div>
            <div class="bcm-section">
                <div class="bcm-label">备注</div>
                <input type="text" class="bcm-note-input ui-input" placeholder="输入备注..." value="${escapeHTML(board.note)}" style="margin-bottom:0;">
            </div>
            <div class="bcm-actions">
                <button class="bcm-save-btn ui-button small-btn">保存</button>
                <button class="bcm-cancel-btn ui-button small-btn danger">取消</button>
            </div>
        `;
        document.body.appendChild(menu);
        const closeMenu = (e) => {
            if (!menu.contains(e.target) && !menu.contains(document.activeElement)) { menu.remove(); document.removeEventListener('click', closeMenu); }
        };
        setTimeout(() => document.addEventListener('click', closeMenu), 0);
        menu.querySelectorAll('.bcm-icon-btn').forEach(btn => {
            btn.onclick = () => {
                board.icon = btn.dataset.icon;
                menu.querySelectorAll('.bcm-icon-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
            };
        });
        menu.querySelector('.bcm-color-input').oninput = (e) => { board.color = e.target.value; };
        const opSlider = menu.querySelector('.bcm-opacity-slider');
        const opVal = menu.querySelector('.bcm-op-val');
        opSlider.oninput = (e) => { board.opacity = parseInt(e.target.value, 10); opVal.textContent = board.opacity + '%'; };
        menu.querySelector('.bcm-save-btn').onclick = () => {
            board.note = menu.querySelector('.bcm-note-input').value.trim();
            saveTodoBoards();
            renderTodoBoards();
            menu.remove();
            document.removeEventListener('click', closeMenu);
            showToast('面板设置已保存');
        };
        menu.querySelector('.bcm-cancel-btn').onclick = () => {
            menu.remove();
            document.removeEventListener('click', closeMenu);
        };
    }
            function bindTrashAwareSortable(sortableEl, options) {
            if (!sortableEl || typeof Sortable === 'undefined') return null;
            return Sortable.create(sortableEl, {
            animation: 350, // 👈 统一改为 350ms，更有呼吸感
            easing: "cubic-bezier(0.34, 1.56, 0.64, 1)", // 👈 注入苹果果冻弹簧曲线
            ghostClass: 'sortable-ghost',
            ...options,
            onStart: (evt) => {
                trashZone.classList.add('visible');
                startDragTracking();
                options.onStart?.(evt);
            },
            onEnd: (evt) => {
                const wasOver = document.body.classList.contains('is-over-trash');
                options.onEnd?.(evt, wasOver);
                stopDragTracking();
            }
        });
    }
