        root.style.setProperty('--preview-scale', Math.max(100, state.previewWidth - 240) / 1920); /* 🌟 注入对应的缩放比例(扣除侧边栏的 240px 占用) */
        root.style.setProperty('--list-view-grid-padding', `${l.listViewGridPadding !== undefined ? l.listViewGridPadding : 2}vw`);
