        root.style.setProperty('--list-view-tile-text-color', l.listViewTileTextAuto ? 'var(--text-b)' : (l.listViewTileTextColor || '#ffffff'));
        root.style.setProperty('--list-view-tile-bg-color', l.listViewTileBgAuto ? 'var(--blob-1)' : (l.listViewTileBgColor || '#ffffff'));
        root.style.setProperty('--list-view-tile-text-display', l.listViewShowTileText === false ? 'none' : 'flex');
        root.style.setProperty('--list-view-tile-anim-duration', l.listViewTileAnimEnabled === false ? '0s' : `${l.listViewTileAnimDuration || 0.45}s`);
        root.style.setProperty('--list-view-sep-display', l.listViewSeparatorEnabled === false ? 'none' : 'block');
        root.style.setProperty('--list-view-sep-style', l.listViewSeparatorStyle || 'dashed');
        root.style.setProperty('--list-view-sep-color', l.listViewSeparatorAuto ? 'var(--blob-1)' : (l.listViewSeparatorColor || '#ffffff'));
        root.style.setProperty('--list-view-clock-size', `${l.listViewClockSize || 66}px`);
        root.style.setProperty('--list-view-search-width', `${l.listViewSearchWidth || 320}px`);
        root.style.setProperty('--list-view-search-height', `${l.listViewSearchHeight || 44}px`);
        root.style.setProperty('--list-view-search-radius', `${l.listViewSearchRadius || 22}px`);
