    if (whFavCurrentBtn) {
        whFavCurrentBtn.onclick = () => {
            if (!state.whCurrentItem || !state.whCurrentItem.id) {
                // 尝试从 whImgUrl 提取 ID 回退
                const match = state.whImgUrl && state.whImgUrl.match(/wallhaven[-_](\w+)/i);
                if (match) {
                    const extractedId = match[1];
                    const exists = state.whFavorites.some(f => f.id === extractedId);
                    if (!exists) {
                        state.whFavorites.push({
                            id: extractedId,
                            path: state.whImgUrl,
                            thumbs: { original: state.whImgUrl },
                            resolution: '',
                            favorites: 0
                        });
                        localStorage.setItem('wh_favorites', JSON.stringify(state.whFavorites));
                        state.whCurrentItem = state.whFavorites[state.whFavorites.length - 1];
                        localStorage.setItem('wh_current_item', JSON.stringify(state.whCurrentItem));
                        if (typeof showToast === 'function') showToast('❤️ 当前背景已加入收藏库');
                    } else {
                        if (typeof showToast === 'function') showToast('⚠️ 当前背景已在收藏库中');
                    }
                } else {
                    if (typeof showToast === 'function') showToast('⚠️ 无法识别当前壁纸信息，请先换一张');
                }
                return;
            }
            const cId = state.whCurrentItem.id;
            if (state.whFavorites.some(f => f.id === cId)) {
                if (typeof showToast === 'function') showToast('⚠️ 当前背景已在收藏库中');
                return;
            }
            state.whFavorites.push({ ...state.whCurrentItem });
            localStorage.setItem('wh_favorites', JSON.stringify(state.whFavorites));
            if (typeof showToast === 'function') showToast('❤️ 当前背景已加入收藏库');
        };
    }
    // ============== Wallhaven 高清响应式壁纸库 - 重构版 ==============
    const whOpenGalleryBtn = document.getElementById('wh-open-gallery-btn');
    const whGalleryModal = document.getElementById('wh-gallery-modal');
    const whGalGrid = document.getElementById('wh-gal-grid');
    const whScrollTop = document.getElementById('wh-gal-scrolltop');
    const whPreviewModal = document.getElementById('wh-preview-modal');
    const whPreviewImg = document.getElementById('wh-preview-img');
    const whPreviewInfo = document.getElementById('wh-preview-info');
    const whPreviewDownload = document.getElementById('wh-preview-download');
    let whGalPage = 1;
    window.whGalMode = 'explore';
