        document.getElementById('wh-gal-search-btn').onclick = () => { window.whGalMode = 'explore'; window.loadWhGallery(true); };
        document.getElementById('wh-gal-fav-btn').onclick = () => { window.whGalMode = 'fav'; window.loadWhGallery(true); };
        document.getElementById('wh-gal-loadmore').onclick = () => window.loadWhGallery(false);
        document.getElementById('wh-gal-q').onkeydown = (e) => { if(e.key === 'Enter') { window.whGalMode = 'explore'; window.loadWhGallery(true); } };
