            whPreviewModal.addEventListener('click', (e) => {
                if (e.target === whPreviewModal) whPreviewModal.classList.remove('open');
            });
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && whPreviewModal.classList.contains('open')) {
                    whPreviewModal.classList.remove('open');
                }
            });
