        updateLayoutVars();
        updateClockStyle();
        updateTransformUI();
        applyBgTransform();
        applyMouseFollowColor();
        updateTimeTool();
        applyUtilityVisibility();
        renderTodoBoards();
        updateMusicUi();
        if (state.currentMusicIndex >= 0 && state.musicPlaylist[state.currentMusicIndex]) {
            setCurrentMusicTrack(state.currentMusicIndex, false);
        }
        if (state.musicAutoplay) {
            setTimeout(() => attemptMusicAutoplay(), 180);
        }
        initMusicPlaylistSortable();
        initSettingSections();
    // =================图标源控制与刷新=================
        const iconSourceButtons = document.querySelectorAll('[data-icon-source]');
        const customIconSettings = document.getElementById('custom-icon-settings');
        const customIconUrlInput = document.getElementById('custom-icon-url');
        const refreshAllIconsBtn = document.getElementById('refresh-all-icons-btn');
        function toggleCustomIconSettings() {
            if (customIconSettings) {
                customIconSettings.style.display = state.iconSource === 'custom' ? 'block' : 'none';
            }
            iconSourceButtons.forEach(btn => {
                btn.classList.toggle('active', btn.dataset.iconSource === state.iconSource);
            });
        }
        if (iconSourceButtons.length > 0) {
            toggleCustomIconSettings();
            iconSourceButtons.forEach(btn => {
                btn.onclick = () => {
                    state.iconSource = btn.dataset.iconSource;
                    localStorage.setItem('icon_source', state.iconSource);
                    toggleCustomIconSettings();
                };
            });
        }
        if (customIconUrlInput) {
            customIconUrlInput.value = state.customIconUrl;
            customIconUrlInput.oninput = (e) => {
                state.customIconUrl = e.target.value.trim();
                localStorage.setItem('custom_icon_url', state.customIconUrl);
            };
        }
        if (refreshAllIconsBtn) {
            refreshAllIconsBtn.onclick = () => {
                if(confirm('⚠️ 警告：这将会清除所有磁贴（包括你手动上传的本地图片）的图标缓存！\n并使用你当前选择的新引擎重新全网抓取。\n\n确定要继续吗？')) {
                    // 遍历彻底删除离线缓存，逼迫其使用新 API 抓取
                    Object.keys(state.data).forEach(cat => {
                        state.data[cat].forEach(item => {
                            if (item.type === 'folder') {
                                item.items.forEach(sub => delete sub.iconBase64);
                            } else {
                                delete item.iconBase64;
                            }
                        });
                    });
                    // 清空当前的搜索引擎缓存图标
                    state.customEngines.forEach(eng => {
                        if(eng.icon && eng.icon.includes('google.com/s2/favicons')) {
                            eng.icon = guessEngineIcon(eng.url);
                        }
                    });
                    localStorage.setItem('custom_engines', JSON.stringify(state.customEngines));
                    window.saveData(); // 保存清除缓存后的状态
                    renderTiles(); // 重新渲染桌面，触发新 API 抓取
                    renderEngineMenu();
                    showToast('♻️ 图标缓存已重置，正在通过新接口重新抓取...');
                }
            };
        }
