              botShadow.className = 'fc-bot-shadow';
              botShadow.style.cssText = 'position:absolute;inset:0;background:#000;pointer-events:none;opacity:0;border-bottom-left-radius:8px;border-bottom-right-radius:8px;';
              botH.appendChild(botShadow);
