              var fontRow = document.createElement('div'); fontRow.className = 'fc-row';
              var fontLbl = document.createElement('label'); fontLbl.textContent = '字体';
              var fontSel = document.createElement('select');
              ['Arial, sans-serif','Courier New, monospace','Times New Roman, serif','Impact, fantasy','Trebuchet MS, sans-serif'].forEach(function(f){
                var o=document.createElement('option');o.value=f;o.textContent=f.split(',')[0].replace(/'/g,'');if(f===fcSettings.fontFamily)o.selected=true;fontSel.appendChild(o);
              });
