        var backdrop = document.createElement('div');
        backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);backdrop-filter:blur(28px);-webkit-backdrop-filter:blur(28px);';
        backdrop.addEventListener('click', function() { item.data.settingsOpen = false; window.saveData(); overlay.remove(); render(); });
