        html += '<div style="font-size:' + Math.round(fs * 0.75) + 'px; color:rgba(255,255,255,0.5); font-weight:600; letter-spacing:0.5px; margin:8px 0 3px 2px;">添加城市</div>';
        const existingNames = new Set(cities.map(c => c.name));
        const availableCities = PRESET_CITIES.filter(c => !existingNames.has(c.name));
        if (availableCities.length === 0) {
            html += '<div style="font-size:' + Math.round(fs * 0.85) + 'px; color:rgba(255,255,255,0.35); padding:4px 8px;">所有预设城市已添加</div>';
        } else {
            html += '<div style="display:flex; flex-wrap:wrap; gap:4px; background:rgba(255,255,255,0.05); border-radius:8px; padding:5px 6px;">';
            for (const pc of availableCities) {
                const diffLabel = getDiffForPreset(pc);
                html += '<span class="wc-add-city" data-name="' + escapeHTML(pc.name) + '" data-tz="' + escapeHTML(pc.timezone) + '" data-offset="' + pc.offset + '"'
                    + ' style="font-size:' + Math.round(fs * 0.85) + 'px; color:rgba(255,255,255,0.7); background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.1); border-radius:12px; padding:3px 8px; cursor:pointer; white-space:nowrap; transition:background 0.15s,color 0.15s;"'
                    + ' onmouseover="this.style.background=\'rgba(255,255,255,0.12)\';this.style.color=\'#fff\'"'
                    + ' onmouseout="this.style.background=\'rgba(255,255,255,0.06)\';this.style.color=\'rgba(255,255,255,0.7)\'">'
                    + escapeHTML(pc.name) + ' <span style="font-size:' + Math.round(fs * 0.65) + 'px; color:rgba(255,255,255,0.35);">' + diffLabel + '</span></span>';
            }
            html += '</div>';
        }
        html += '</div>';
        bodyEl.innerHTML = '';
        var panel = document.createElement('div');
        panel.className = 'wc-settings-panel';
        panel.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(30,30,46,0.95);backdrop-filter:blur(28px);-webkit-backdrop-filter:blur(28px);border:1px solid rgba(255,255,255,0.1);border-radius:12px;box-shadow:0 12px 48px rgba(0,0,0,0.5);max-height:85vh;overflow-y:auto;width:calc(100% - 16px);max-width:420px;';
        panel.addEventListener('click', function(e) { e.stopPropagation(); });
        panel.innerHTML = html;
        overlay.appendChild(backdrop);
        overlay.appendChild(panel);
        document.body.appendChild(overlay);
        // 关闭按钮
        const closeBtn = overlay.querySelector('.wc-set-close');
        if (closeBtn) {
            closeBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                item.data.settingsOpen = false;
                window.saveData();
                overlay.remove();
                render();
            });
        }
