// ==========================================
// 🚀 终极物理模拟版：自由飘散烟花特效
// ==========================================
function triggerConfetti(startX, startY) {
    if (!ctx || !confettiCanvas) return;
    // 自动适配全屏画布大小
    confettiCanvas.width = window.innerWidth;
    confettiCanvas.height = window.innerHeight;
    const particles = [];
    const colors = ['#ff3b30', '#ff9500', '#ffcc00', '#4cd964', '#5ac8fa', '#007aff', '#5856d6', '#ff2d55', '#ffffff'];
    // 增加粒子数量，让效果更“散”更壮观
    const particleCount = 140;
    for (let i = 0; i < particleCount; i++) {
        // 1. 爆炸初速度：极快且发散角度大
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 35 + 10; // 极高的初速度
        particles.push({
            x: startX,
            y: startY,
            // 物理参数
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed - 10, // 初始给一个向上的冲力
            friction: 0.94,    // 空气阻力：数值越小减速越快 (0.9-0.96 最佳)
            gravity: 0.15,     // 极轻的重力，模拟纸屑下落
            // 2. 自由飘荡参数（模拟空气流过纸片边缘的摇晃）
            wobble: Math.random() * Math.PI * 2,
            wobbleSpeed: Math.random() * 0.1 + 0.05,
            wobbleRange: Math.random() * 8 + 4,
            // 外观
            size: Math.random() * 8 + 4,
            color: colors[Math.floor(Math.random() * colors.length)],
            shape: Math.random() > 0.5 ? 'rect' : 'circle',
            tilt: Math.random() * 10,
            tiltAngle: Math.random() * 0.1,
            // 3. 生命周期：约 3 秒消失 (60帧/秒 * 3 = 180帧)
            // 我们让它在前 1.5 秒保持鲜艳，后 1.5 秒缓慢变淡
            opacity: 1,
            life: 1.0,
            decay: Math.random() * 0.005 + 0.006 // 平均 160-200 帧耗尽
        });
    }
    function draw() {
        ctx.clearRect(0, 0, confettiCanvas.width, confettiCanvas.height);
        let alive = false;
        particles.forEach(p => {
            if (p.opacity <= 0) return;
            alive = true;
            // --- 物理逻辑计算 ---
            // 1. 阻力与重力
            p.vx *= p.friction;
            p.vy *= p.friction;
            p.vy += p.gravity;
            // 2. 核心：自由摇曳逻辑 (基于正弦波模拟空气阻力产生的横向位移)
            p.wobble += p.wobbleSpeed;
            const drift = Math.sin(p.wobble) * p.wobbleRange * (p.life); // 速度慢下来后，摇摆更明显
            p.x += p.vx + drift * 0.2; // 结合惯性和空气漂移
            p.y += p.vy;
            // 3. 旋转效果
            p.tiltAngle += 0.1;
            // 4. 衰减逻辑
            p.life -= p.decay;
            // 只有当生命值低于 0.6 时才开始线性淡出，保证前段视觉饱满
            if (p.life < 0.6) {
                p.opacity = p.life / 0.6;
            }
            // --- 绘图 ---
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.wobble); // 随摇摆旋转
            ctx.globalAlpha = p.opacity;
            ctx.fillStyle = p.color;
            // 添加极光微光感
            ctx.shadowBlur = 4;
            ctx.shadowColor = p.color;
            ctx.beginPath();
            if (p.shape === 'circle') {
                ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
            } else {
                // 绘制一个带倾角的长方形纸屑
                const w = p.size;
                const h = p.size * 0.6;
                ctx.rect(-w / 2, -h / 2, w, h);
            }
            ctx.fill();
            ctx.restore();
        });
        if (alive) {
            requestAnimationFrame(draw);
        } else {
            ctx.clearRect(0, 0, confettiCanvas.width, confettiCanvas.height);
        }
    }
    draw();
}
    function rotateEngine(open) {
        if (state.isAnimating) return;
        state.isAnimating = true;
        if (open) {
            curEngIcon.classList.remove('rotate-360');
            void curEngIcon.offsetWidth;
            curEngIcon.classList.add('rotate-180');
            engineMenu.classList.add('open');
        } else {
            engineMenu.classList.remove('open');
            curEngIcon.classList.remove('rotate-180');
            curEngIcon.classList.add('rotate-360');
            curEngIcon.addEventListener('transitionend', function handler() {
                if (curEngIcon.classList.contains('rotate-360')) {
                    curEngIcon.style.transition = 'none';
                    curEngIcon.classList.remove('rotate-360');
                    curEngIcon.style.transform = 'rotate(0deg)';
                    void curEngIcon.offsetWidth;
                    curEngIcon.style.transition = '';
                }
                curEngIcon.removeEventListener('transitionend', handler);
            }, { once: true });
        }
        setTimeout(() => state.isAnimating = false, 600);
    }
