    // 🌍 智能追加国家过滤参数
    function applyCountryCode(url, countryCode) {
        if (!countryCode) return url;
        const code = countryCode.toLowerCase();
        // 🚀 核心映射：为了防止界面仍然显示中文，必须同时向搜索引擎发送该国的主流“语言指令 (Language)”
        const langMap = {
            'us': 'en', 'gb': 'en', 'ca': 'en', 'au': 'en', 'nz': 'en', 'ie': 'en', 'za': 'en', 'sg': 'en', 'in': 'en',
            'jp': 'ja', 'kr': 'ko', 'de': 'de', 'ch': 'de', 'fr': 'fr', 'ru': 'ru', 'br': 'pt', 'it': 'it',
            'es': 'es', 'mx': 'es', 'ar': 'es', 'id': 'id', 'sa': 'ar', 'ae': 'ar', 'eg': 'ar', 'tr': 'tr',
            'se': 'sv', 'nl': 'nl', 'my': 'ms', 'th': 'th', 'vn': 'vi', 'ph': 'tl', 'pl': 'pl', 'cn': 'zh-CN'
        };
        const lang = langMap[code] || 'en'; // 默认保底使用英语
        // Google
        if (url.includes('google.com') || url.includes('google.co')) {
            // gl = 地区代码 (Geo Location), hl = 界面语言 (Host Language)
            return url + `&gl=${code}&hl=${lang}`;
        }
        // Bing
        if (url.includes('bing.com')) {
            // cc = 国家代码 (Country Code), setlang = 界面语言
            return url + `&cc=${code}&setlang=${lang}`;
        }
        // DuckDuckGo
        if (url.includes('duckduckgo.com')) {
            // kl = 地区-语言混合代码
            return url + `&kl=${code}-${lang}`;
        }
        // Yahoo
        if (url.includes('yahoo.com')) {
            return url + `&vc=${code}&vl=${lang}`;
        }
        return url;
    }
    // 🚀 强力防拦截的多并发开窗引擎
    function openSearchTab(url, index = 0, forceNewTab = true) {
        // 如果是强制在当前页打开，且是第一个页面，则直接替换当前页（防历史记录污染）
        if (!forceNewTab && index === 0) {
            window.location.replace(url);
            return;
        }
        // 1. 特权模式：如果是作为 Chrome/Edge 扩展运行，调用底层 API 绝对不会被拦截！
        if (window.chrome && chrome.tabs && chrome.tabs.create) {
            chrome.tabs.create({ url: url, active: index === 0 }); // 让第一个标签页激活，其他的在后台静默加载防晃眼
            return;
        }
        // 2. 网页模式：采用时间差错位发射，规避瞬间并发引发的强力拦截
        setTimeout(() => {
            const newWin = window.open(url, '_blank');
            // 如果返回 null，说明被浏览器拦截了，向用户发出白名单申请提示
            if (!newWin && index === 1 && typeof showToast === 'function') {
                showToast('⚠️ 浏览器拦截了多开页面！请点击地址栏右侧的【拦截图标】->【始终允许】');
            }
        }, index * 100); // 每个页面间隔 100 毫秒
    }
