    copyOcrResultBtn.onclick = () => copyText(ocrOutput.value.trim(), 'OCR 结果已复制');
    ocrPickBtn.onclick = () => ocrInput.click();
    async function processOcrFile(file) {
        if (!file) return;
        ocrStatus.innerText = '准备识别...';
        ocrOutput.value = '';
        const engine = state.ocrEngine || 'tesseract';
        try {
            if (engine === 'tesseract') {
                try {
                    await loadOcrRuntime();
                } catch (err) {
                    ocrStatus.innerText = location.protocol === 'chrome-extension:' || location.protocol === 'edge-extension:'
                        ? '扩展受限，请使用下方拉框切换云端引擎！'
                        : 'OCR 引擎加载失败';
                    return;
                }
                ocrStatus.innerText = '本地模型加载中...';
                const result = await window.Tesseract.recognize(file, 'chi_sim+eng', {
                    logger: ({ status, progress }) => {
                        ocrStatus.innerText = `${status} ${progress ? `${Math.round(progress * 100)}%` : ''}`.trim();
                    }
                });
                ocrOutput.value = result?.data?.text?.trim() || '';
                ocrStatus.innerText = ocrOutput.value ? '识别完成 (Tesseract)' : '未识别到文本';
                if (ocrOutput.value) playSuccessBeep();
            } else if (engine.startsWith('ocrspace')) {
                ocrStatus.innerText = '云端引擎处理中 (请稍等)...';
                let ocrEngineNum = '1';
                let lang = 'chs';
                if (engine === 'ocrspace_2') ocrEngineNum = '2';
                if (engine === 'ocrspace_3') ocrEngineNum = '3';
                if (engine === 'ocrspace_kor') lang = 'kor';
                if (engine === 'ocrspace_jpn') lang = 'jpn';
                const formData = new FormData();
                formData.append('file', file);
                formData.append('language', lang);
                formData.append('apikey', getApi('ocr_space').key);
                formData.append('OCREngine', ocrEngineNum);
                formData.append('isTable', 'true'); // 🌟 核心：开启表格与物理排版保留模式，防止文字全部挤在一起
                const response = await fetch(getApi('ocr_space').url, { method: 'POST', body: formData });
                if (!response.ok) throw new Error(`云端服务响应异常: ${response.status}`);
                const data = await response.json();
                if (data.IsErroredOnProcessing) throw new Error(data.ErrorMessage ? data.ErrorMessage[0] : '识别出错');
                let text = '';
                if (data.ParsedResults && data.ParsedResults.length > 0) {
                    text = data.ParsedResults.map(r => r.ParsedText).join('\n');
                }
                ocrOutput.value = text.trim();
                ocrStatus.innerText = ocrOutput.value ? '识别完成 (OCR.Space)' : '未识别到文本';
                if (ocrOutput.value) playSuccessBeep();
            }
        } catch (err) {
            console.error(err);
            ocrStatus.innerText = '识别失败：' + (err.message || '网络或接口限制');
        } finally {
            if (ocrInput) ocrInput.value = '';
        }
    }
    ocrInput.onchange = (e) => processOcrFile(e.target.files[0]);
    const ocrPasteZone = document.getElementById('ocr-paste-zone');
    if (ocrPasteZone) {
        ocrPasteZone.onclick = () => {
            ocrPasteZone.focus();
            if (typeof showToast === 'function') showToast('已选中区域，请按 Ctrl+V 粘贴图片');
        };
        ocrPasteZone.addEventListener('paste', (e) => {
            e.preventDefault();
            const items = (e.clipboardData || window.clipboardData).items;
            let imageFound = false;
            for (let item of items) {
                if (item.type.indexOf('image') === 0) {
                    imageFound = true;
                    processOcrFile(item.getAsFile());
                    break;
                }
            }
            if (!imageFound && typeof showToast === 'function') showToast('剪贴板中未检测到图片');
        });
        ocrPasteZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            ocrPasteZone.style.borderColor = 'var(--text-b)';
            ocrPasteZone.style.background = 'rgba(255,255,255,0.05)';
        });
        ocrPasteZone.addEventListener('dragleave', (e) => {
            e.preventDefault();
            ocrPasteZone.style.borderColor = 'rgba(255,255,255,0.3)';
            ocrPasteZone.style.background = '';
        });
        ocrPasteZone.addEventListener('drop', (e) => {
            e.preventDefault();
            ocrPasteZone.style.borderColor = 'rgba(255,255,255,0.3)';
            ocrPasteZone.style.background = '';
            if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                const file = e.dataTransfer.files[0];
                if (file.type.startsWith('image/')) {
                    processOcrFile(file);
                } else {
                    if (typeof showToast === 'function') showToast('请拖入图片文件');
                }
            }
        });
    }
