// ==========================================
    // 10. 🚀 Java 后端同步与头像上传核心逻辑
    // ==========================================
    const API_BASE = "http://127.0.0.1:8080/api/user";
    // 🔲 碰撞检测与推开算法（用于自由布局模式下的磁贴缩放）
    // 自由布局：解决磁贴碰撞并推开其他磁贴
    function resolveFreeLayoutCollisions(movedItem, allItems, cat, gridStepX, gridStepY) {
        if (!state.freeLayout) return false;
        // 构建所有其他磁贴的矩形（使用实际宽高）
        const tiles = [];
        for (const item of allItems) {
            if (item === movedItem) continue;
            tiles.push({
                item: item,
                x: item.x || 0,
                y: item.y || 0,
                w: (item.width || 1) * gridStepX,
                h: (item.height || 1) * gridStepY
            });
        }
        // 移动磁贴的矩形（位置固定，不会再移动）
        const movedRect = {
            x: movedItem.x || 0,
            y: movedItem.y || 0,
            w: (movedItem.width || 1) * gridStepX,
            h: (movedItem.height || 1) * gridStepY
        };
        let changed = false;
        let maxIterations = 20;
        let iter = 0;
        // 迭代解决碰撞（向下推开）
        while (iter++ < maxIterations) {
            let anyCollision = false;
            // 按 Y 坐标排序，从上到下处理
            tiles.sort((a, b) => a.y - b.y);
            for (let i = 0; i < tiles.length; i++) {
                const tile = tiles[i];
                const rect = { x: tile.x, y: tile.y, w: tile.w, h: tile.h };
                // 与移动磁贴碰撞 → 向下推
                if (rect.x < movedRect.x + movedRect.w &&
                    rect.x + rect.w > movedRect.x &&
                    rect.y < movedRect.y + movedRect.h &&
                    rect.y + rect.h > movedRect.y) {
                    const newY = movedRect.y + movedRect.h;
                    if (newY > tile.y) {
                        tile.y = newY;
                        tile.item.y = newY;
                        anyCollision = true;
                        changed = true;
                    }
                }
                // 与其他已调整过的磁贴碰撞 → 继续向下推
                for (let j = 0; j < i; j++) {
                    const other = tiles[j];
                    if (tile === other) continue;
                    const otherRect = { x: other.x, y: other.y, w: other.w, h: other.h };
                    if (rect.x < otherRect.x + otherRect.w &&
                        rect.x + rect.w > otherRect.x &&
                        rect.y < otherRect.y + otherRect.h &&
                        rect.y + rect.h > otherRect.y) {
                        const newY = otherRect.y + otherRect.h;
                        if (newY > tile.y) {
                            tile.y = newY;
                            tile.item.y = newY;
                            anyCollision = true;
                            changed = true;
                            break;
                        }
                    }
                }
            }
            if (!anyCollision) break;
        }
        // === 向上紧凑归位：防止单向下推造成的累积漂移 ===
        const allTiles = [
            { x: movedRect.x, y: movedRect.y, w: movedRect.w, h: movedRect.h, item: movedItem },
            ...tiles
        ];
        allTiles.sort((a, b) => a.y - b.y);
        const compacted = [];
        for (const tile of allTiles) {
            let maxBottom = 0;
            // 找所有水平重叠且已归位的磁贴，取最大底部
            for (const p of compacted) {
                if (tile.x < p.x + p.w && tile.x + tile.w > p.x) {
                    maxBottom = Math.max(maxBottom, p.y + p.h);
                }
            }
            if (maxBottom < tile.y - 1) {
                tile.y = maxBottom;
                tile.item.y = maxBottom;
                changed = true;
            }
            compacted.push({ x: tile.x, y: tile.y, w: tile.w, h: tile.h });
        }
        return changed;
    }
    // 兼容旧接口（用于缩放结束）
    function detectAndPushTiles(currentItem, newWidth, newHeight, allItems, cat) {
        if (!state.freeLayout) return allItems;
        // 更新当前磁贴的宽高
        currentItem.width = newWidth;
        currentItem.height = newHeight;
        currentItem.freeLayoutWidth = newWidth;
        currentItem.freeLayoutHeight = newHeight;
        const gridStepX = parseInt(state.layout.tileSize) + 28;
        const gridStepY = parseInt(state.layout.tileSize) + 26;
        // 执行碰撞检测
        resolveFreeLayoutCollisions(currentItem, allItems, cat, gridStepX, gridStepY);
        return allItems;
    }
