    async function updateMemoryDetails() {
        const modal = document.getElementById('memory-detail-modal');
        if (!modal || !modal.classList.contains('open')) return;
        const content = document.getElementById('memory-detail-content');
        if (!content) return;
        // 获取系统内存
        const getSystemMemory = () => {
            return new Promise((resolve) => {
                if (typeof chrome !== 'undefined' && chrome.system && chrome.system.memory) {
                    chrome.system.memory.getInfo((info) => {
                        if (chrome.runtime.lastError) {
                            console.warn('Chrome 内存 API 错误:', chrome.runtime.lastError);
                            resolve(null);
                        } else {
                            resolve({
                                available: info.availableCapacity,
                                capacity: info.capacity,
                                used: info.capacity - info.availableCapacity
                            });
                        }
                    });
                } else {
                    resolve(null);
                }
            });
        };
        const sysMem = await getSystemMemory();
        if (sysMem) {
            // 显示系统内存
            const usedMB = (sysMem.used / (1024 * 1024)).toFixed(1);
            const totalMB = (sysMem.capacity / (1024 * 1024)).toFixed(1);
            const availMB = (sysMem.available / (1024 * 1024)).toFixed(1);
            const percent = Math.round((sysMem.used / sysMem.capacity) * 100);
            content.innerHTML = `
                <div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 8px;">
                    <span>系统总内存：</span>
                    <span style="font-weight: bold;">${totalMB} MB</span>
                </div>
                <div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 8px;">
                    <span>已使用：</span>
                    <span style="font-weight: bold; color: ${percent >= 90 ? '#ff453a' : (percent >= 75 ? '#f59e0b' : '#34c759')};">${usedMB} MB</span>
                </div>
                <div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 8px;">
                    <span>可用内存：</span>
                    <span style="font-weight: bold;">${availMB} MB</span>
                </div>
                <div style="display: flex; justify-content: space-between; padding-bottom: 8px; margin-bottom: 8px;">
                    <span>使用率：</span>
                    <span style="font-weight: bold; color: ${percent >= 90 ? '#ff453a' : (percent >= 75 ? '#f59e0b' : 'inherit')};">${percent}%</span>
                </div>
                <div style="font-size: 12px; color: rgba(255,255,255,0.5); margin-top: 10px; line-height: 1.5;">
                    * 系统物理内存（通过 Chrome API 获取）
                </div>
            `;
        } else if (window.performance && performance.memory) {
            // 降级显示网页内存
            const mem = performance.memory;
            const used = (mem.usedJSHeapSize / (1024 * 1024)).toFixed(1);
            const total = (mem.totalJSHeapSize / (1024 * 1024)).toFixed(1);
            const limit = (mem.jsHeapSizeLimit / (1024 * 1024)).toFixed(1);
            const percent = Math.round((mem.usedJSHeapSize / mem.jsHeapSizeLimit) * 100);
            content.innerHTML = `
                <div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 8px;">
                    <span>JS 堆已分配：</span>
                    <span style="font-weight: bold;">${total} MB</span>
                </div>
                <div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 8px;">
                    <span>JS 堆使用中：</span>
                    <span style="font-weight: bold; color: ${percent >= 90 ? '#ff453a' : (percent >= 75 ? '#f59e0b' : '#34c759')};">${used} MB</span>
                </div>
                <div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px; margin-bottom: 8px;">
                    <span>JS 堆上限：</span>
                    <span style="font-weight: bold;">${limit} MB</span>
                </div>
                <div style="display: flex; justify-content: space-between; padding-bottom: 8px; margin-bottom: 8px;">
                    <span>使用率：</span>
                    <span style="font-weight: bold; color: ${percent >= 90 ? '#ff453a' : (percent >= 75 ? '#f59e0b' : 'inherit')};">${percent}%</span>
                </div>
                <div style="font-size: 12px; color: rgba(255,255,255,0.5); margin-top: 10px; line-height: 1.5;">
                    * 仅显示当前网站页面的 JavaScript 堆内存
                </div>
            `;
        } else {
            content.innerHTML = '<div style="text-align: center; padding: 10px 0;">当前环境不支持读取内存信息</div>';
        }
    }
