                                '&daily=temperature_2m_max,temperature_2m_min,weather_code,wind_speed_10m_max,wind_direction_10m_dominant,sunrise,sunset,uv_index_max,precipitation_probability_max' +
                                '&hourly=temperature_2m,precipitation_probability,weather_code,wind_speed_10m,wind_direction_10m' +
                                '&timezone=auto&forecast_days=14';
                            var omCtrl = new AbortController();
