    updateWeatherVisibility();
    // ==========================================
    // 🎨 全局智能四角取色引擎 (支持图片、视频)
    // ==========================================
    function applySmartThemeColor() {
        const root = document.documentElement;
        // 如果是极光模式，调用纯极光逻辑
        if (state.bgMode === 'mesh') {
            return updateThemeColor();
        }
        // 如果是交互背景模式，设置对应主题的颜色
        if (state.bgMode === 'interactive') {
            const interactiveTheme = localStorage.getItem('interactiveTheme') || 'earth';
            const themeColors = {
                'earth': { b1: '#1e40af', b2: '#3b82f6', b3: '#60a5fa', b4: '#93c5fd', b5: '#dbeafe' }, // 蓝色系
                'solar': { b1: '#dc2626', b2: '#ea580c', b3: '#f59e0b', b4: '#fbbf24', b5: '#fcd34d' }, // 红色到金色
                'saturn': { b1: '#92400e', b2: '#d97706', b3: '#f59e0b', b4: '#fbbf24', b5: '#fed7aa' }, // 金棕色系
                'quantum': { b1: '#7c3aed', b2: '#a855f7', b3: '#c084fc', b4: '#ddd6fe', b5: '#e9d5ff' }, // 紫色系
                'cyber': { b1: '#00f2fe', b2: '#f012be', b3: '#7c3aed', b4: '#06b6d4', b5: '#ec4899' }, // 青粉紫色
                'manifold': { b1: '#06b6d4', b2: '#3b82f6', b3: '#8b5cf6', b4: '#ec4899', b5: '#f97316' }  // 多彩渐变
            };
            const colors = themeColors[interactiveTheme] || themeColors['earth'];
            root.style.setProperty('--bg-base', '#0f172a');
            root.style.setProperty('--blob-1', colors.b1);
            root.style.setProperty('--blob-2', colors.b2);
            root.style.setProperty('--blob-3', colors.b3);
            root.style.setProperty('--blob-4', colors.b4);
            root.style.setProperty('--blob-5', colors.b5);
            root.style.setProperty('--text-a', '#ffffff');
            root.style.setProperty('--text-b', colors.b1);
            // 刷新时钟
            if (typeof updateClockStyle === 'function') updateClockStyle();
            return;
        }
        let sourceElement = null;
        let mediaW = 0, mediaH = 0;
        // 1. 动态视频取色
        if (state.bgMode === 'live' && bgVideo) {
            if (bgVideo.readyState >= 2) {
                sourceElement = bgVideo;
                mediaW = bgVideo.videoWidth;
                mediaH = bgVideo.videoHeight;
                extractAndSet();
            } else {
                // 监听视频加载出第一帧的瞬间
                bgVideo.addEventListener('loadeddata', () => {
                    sourceElement = bgVideo;
                    mediaW = bgVideo.videoWidth;
                    mediaH = bgVideo.videoHeight;
                    extractAndSet();
                }, { once: true });
                return;
            }
        }
        // 2. 图片类壁纸取色 (Bing, 自选本地图片)
        else if (state.bgMode === 'bing' || state.bgMode === 'custom' || state.bgMode === 'wallhaven') {
            const imgSrc = state.bgMode === 'bing' ? state.bingImgUrl : (state.bgMode === 'wallhaven' ? state.whImgUrl : (state.customImgData || state.customImgUrl));
            if (imgSrc) {
                const img = new Image();
                img.crossOrigin = 'anonymous'; // 尝试突破跨域
                img.onload = () => {
                    sourceElement = img;
                    mediaW = img.width;
                    mediaH = img.height;
                    extractAndSet();
                };
                img.src = imgSrc;
            }
        }
        // 核心取色运算：分别获取画面的 左上/右上/左下/右下/中心
        function extractAndSet() {
            try {
                const canvas = document.createElement('canvas');
                canvas.width = mediaW;
                canvas.height = mediaH;
                const ctx = canvas.getContext('2d');
                ctx.drawImage(sourceElement, 0, 0, mediaW, mediaH);
                // 辅助函数：抓取指定坐标的区块平均色
                const getBlockColor = (x, y) => {
                    // 取画面 10% 大小的正方形区块进行混色，避免取到噪点
                    const sizeX = Math.max(10, mediaW / 10);
                    const sizeY = Math.max(10, mediaH / 10);
                    const data = ctx.getImageData(x, y, sizeX, sizeY).data;
                    let r = 0, g = 0, b = 0, count = 0;
                    for (let i = 0; i < data.length; i += 4) {
                        // 过滤掉暗沉色和透明像素，让提取的主题色更亮眼
                        if (data[i + 3] > 128) {
                            r += data[i]; g += data[i + 1]; b += data[i + 2];
                            count++;
                        }
                    }
                    if (count === 0) return '#a5b4fc'; // 保底色
                    return `rgb(${Math.round(r/count)}, ${Math.round(g/count)}, ${Math.round(b/count)})`;
                };
                const blockW = mediaW / 10;
                const blockH = mediaH / 10;
                const cTL = getBlockColor(0, 0);                               // 左上角
                const cTR = getBlockColor(mediaW - blockW, 0);                 // 右上角
                const cBL = getBlockColor(0, mediaH - blockH);                 // 左下角
                const cBR = getBlockColor(mediaW - blockW, mediaH - blockH);   // 右下角
                const cCenter = getBlockColor(mediaW/2 - blockW/2, mediaH/2 - blockH/2); // 画面中心
                // 写入全局 CSS 变量！
                root.style.setProperty('--bg-base', '#0f172a');
                root.style.setProperty('--blob-1', cTL);
                root.style.setProperty('--blob-2', cTR);
                root.style.setProperty('--blob-3', cBL);
                root.style.setProperty('--blob-4', cBR);
                root.style.setProperty('--blob-5', cCenter);
                // 让左上角颜色作为 UI 核心色（时钟也将完美吸附这个颜色）
                root.style.setProperty('--text-b', cTL);
                // 刷新时钟
                if (typeof updateClockStyle === 'function') updateClockStyle();
            } catch (e) {
                console.warn("因跨域安全策略无法取色，已使用默认高光色");
            }
        }
    }
    // 仅保留给极光模式用的纯渲染逻辑
    function updateThemeColor() {
        if (state.bgMode !== 'mesh') return;
        const root = document.documentElement;
        if (!state.useMeshAuto) {
            root.style.setProperty('--bg-base', '#0f172a');
            root.style.setProperty('--blob-1', state.meshColors[0]);
            root.style.setProperty('--blob-2', state.meshColors[1]);
            root.style.setProperty('--blob-3', state.meshColors[2]);
            root.style.setProperty('--blob-4', state.meshColors[3]);
            root.style.setProperty('--blob-5', state.meshColors[4]);
            root.style.setProperty('--text-a', '#ffffff');
            root.style.setProperty('--text-b', state.meshColors[0]);
            return;
        }
        const h = new Date().getHours();
        const theme = getThemeByHour(MESH_THEMES, h);
        root.style.setProperty('--bg-base', theme.base);
        root.style.setProperty('--blob-1', theme.b1);
        root.style.setProperty('--blob-2', theme.b2);
        root.style.setProperty('--blob-3', theme.b3);
        root.style.setProperty('--blob-4', theme.b4);
        root.style.setProperty('--blob-5', theme.b5);
        root.style.setProperty('--text-a', theme.ta);
        root.style.setProperty('--text-b', theme.tb);
    }
// ==========================================
    // 💡 零延迟智能搜索补全 (带缓存与高亮)
    // ==========================================
    const suggestionBox = document.getElementById('searchSuggestions');
    const suggestionList = document.getElementById('suggestionList');
    let suggestionTimer = null;
    let currentSuggestions = [];
    let selectedSuggestionIndex = -1;
    let currentKeyword = '';
    // 🚀 核心优化：内存级缓存字典。查过一次的词秒出结果，0网络请求
    const suggestionCache = {};
    window.handleSearchSuggestions = function(data) {
        let results = [];
        if (data && data.s) {
            results = data.s;
        }
        // 数据存入缓存
        if (currentKeyword) {
            suggestionCache[currentKeyword] = results;
        }
        currentSuggestions = results.slice(0, 8); // 最多展示 8 条
        renderSuggestions(currentKeyword);
    };
    window.showHistory = function() {
        if (!state.showSearchHistory || state.isIncognitoSearch || !state.searchHistory.length) {
            hideSuggestions();
            return;
        }
        currentSuggestions = [...state.searchHistory];
        currentKeyword = ''; // 清空 currentKeyword 代表当前处于历史模式
        let html = `<div style="display:flex; justify-content:space-between; align-items:center; padding: 4px 16px 8px; border-bottom: 1px solid rgba(255,255,255,0.05); margin-bottom: 4px;">
            <span style="font-size:11px; color:rgba(255,255,255,0.4); font-weight: bold; letter-spacing: 1px;">最近搜索记录</span>
            <span class="search-clear-history-btn" style="font-size:11px; color:rgba(255,255,255,0.4); cursor:pointer; transition:0.2s;" onmouseover="this.style.color='#ff453a'" onmouseout="this.style.color='rgba(255,255,255,0.4)'">清空记录</span>
        </div>`;
        html += currentSuggestions.map((item, index) => `
            <div class="suggestion-item history-item ${index === selectedSuggestionIndex ? 'selected' : ''}" data-index="${index}" style="position:relative; padding-right: 60px;">
                <span class="suggestion-item-icon">🕒</span>
                <span class="suggestion-text" style="opacity: 0.9;">${item.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</span>
                <span class="delete-history-btn" data-index="${index}" style="position:absolute; right:16px; font-size:16px; opacity:0; transition:0.2s; cursor:pointer;" onmouseover="this.style.color='#ff453a'">×</span>
            </div>
        `).join('');
        suggestionList.innerHTML = html;
        suggestionBox.setAttribute('data-type', 'history');
        suggestionBox.classList.add('show');
        suggestionBox.querySelectorAll('.history-item').forEach(el => {
            el.onclick = (e) => {
                if(e.target.classList.contains('delete-history-btn')) return;
                searchInput.value = state.searchHistory[el.dataset.index];
                hideSuggestions();
                if (state.historyAction === 'direct') {
                    doSearch();
                } else {
                    searchInput.focus();
                }
            };
            el.onmouseover = () => { const delBtn = el.querySelector('.delete-history-btn'); if(delBtn) delBtn.style.opacity = '1'; };
            el.onmouseout = () => { const delBtn = el.querySelector('.delete-history-btn'); if(delBtn) delBtn.style.opacity = '0'; };
        });
        suggestionBox.querySelectorAll('.delete-history-btn').forEach(btn => {
            btn.onclick = (e) => {
                e.stopPropagation();
                state.searchHistory.splice(btn.dataset.index, 1);
                localStorage.setItem('search_history', JSON.stringify(state.searchHistory));
                showHistory();
            };
        });
        const clearBtn = suggestionBox.querySelector('.search-clear-history-btn');
        if (clearBtn) {
            clearBtn.onclick = (e) => {
                e.stopPropagation();
                state.searchHistory = [];
                localStorage.setItem('search_history', '[]');
                hideSuggestions();
            };
        }
    };
