    const tz = document.getElementById('trash-zone');
    if (tz) {
        // 监听拖拽悬浮
        tz.addEventListener('dragover', (e) => {
            const isMediaDragging = document.querySelector('.music-playlist .sortable-ghost') || document.querySelector('.music-playlist .sortable-drag');
            const isAudioDragging = document.querySelector('.alarm-sound-list .library-item.dragging');
            const isTimeZoneDragging = document.querySelector('.time-zone-item.dragging') || (() => {
                if (!e.dataTransfer) return false;
                try {
                    const data = e.dataTransfer.getData('text/plain');
                    const payload = data ? JSON.parse(data) : null;
                    return payload && payload.type === 'timeZone';
                } catch {
                    return false;
                }
            })();
            if (isMediaDragging || isAudioDragging || isTimeZoneDragging) {
                e.preventDefault();
                tz.style.borderColor = '#ff4d4f';
                tz.style.background = 'rgba(255, 77, 79, 0.15)';
            }
        });
        tz.addEventListener('dragleave', () => {
            tz.style.borderColor = '';
            tz.style.background = '';
        });
        tz.addEventListener('drop', (e) => {
            let handled = false;
            const draggedMediaItem = document.querySelector('.music-playlist .sortable-ghost') || document.querySelector('.music-playlist .sortable-drag');
            if (draggedMediaItem) {
                e.preventDefault();
                handled = true;
                draggedMediaItem.remove();
            } else {
                try {
                    const data = e.dataTransfer?.getData('text/plain');
                    if (data) {
                        const payload = JSON.parse(data);
                        if (payload && payload.type === 'timeZone' && typeof window.removeTimeZone === 'function') {
                            e.preventDefault();
                            handled = true;
                            window.removeTimeZone(Number(payload.index));
                        } else if (payload && payload.type === 'alarmSound' && typeof window.deleteAlarmSound === 'function') {
                            e.preventDefault();
                            handled = true;
                            window.deleteAlarmSound(payload.id);
                        }
                    }
                } catch {}
            }
            if (handled) {
                tz.style.borderColor = '';
                tz.style.background = '';
                const trashText = tz.querySelector('.trash-text');
                if (trashText) {
                    const originalHtml = trashText.innerHTML;
                    trashText.innerHTML = '<span style="color:#ff453a; font-weight:bold;">✅ 已删除</span>';
                    setTimeout(() => { trashText.innerHTML = originalHtml; }, 1500);
                }
            }
        });
    }
    // ==========================================
    // 🎚️ 进度条 (Range) 动态高亮填充引擎
    // ==========================================
    document.querySelectorAll('input[type="range"]').forEach(range => {
        // 计算并更新宽度的核心函数
        const updateRangeProgress = () => {
            const min = parseFloat(range.min || 0);
            const max = parseFloat(range.max || 100);
            const val = parseFloat(range.value || 0);
            // 计算当前值在极值中的百分比
            const percent = ((val - min) / (max - min)) * 100;
            // 将百分比传递给 CSS 变量 --progress
            range.style.setProperty('--progress', `${percent}%`);
        };
        // 1. 页面加载时，先初始化一次所有进度条的位置
        updateRangeProgress();
        // 2. 监听用户鼠标拖动时的实时更新
        range.addEventListener('input', updateRangeProgress);
        // 3. 兼容刚才的“点击精确输入”功能，当数值被强行修改时，也能触发轨道更新
        range.addEventListener('change', updateRangeProgress);
    });
