        // 核心安全防误触：如果点击的是搜索栏本体、引擎切换下拉、或联想词弹窗内部，则不退出
        if (searchContainerDom && searchContainerDom.contains(e.target)) return;
        // 点击外部区域时，隐藏联想词弹窗
        if (typeof hideSuggestions === 'function') hideSuggestions();
        // 如果当前不在聚焦模式，直接放行，无需执行沉浸模式的还原动画
        if (!document.body.classList.contains('search-focus-active')) return;
        // 触发丝滑退出动画
        exitSearchFocus();
        if (document.activeElement === searchInput) {
            searchInput.blur();
        }
