    // ==========================================
    function toggleIncognitoSearch() {
        state.isIncognitoSearch = !state.isIncognitoSearch;
        localStorage.setItem('is_incognito_search', state.isIncognitoSearch);
        updateIncognitoVisuals();
        if (state.isIncognitoSearch) {
            const isMac = navigator.userAgent.indexOf("Mac") !== -1;
            const shortcut = isMac ? "Command + Shift + N" : "Ctrl + Shift + N";
            showToast(`🕶️ 无痕已开启 (提示: 浏览器原生 ${shortcut} 效果更好)`);
        } else {
            showToast('✅ 无痕搜索已关闭');
        }
    }
    function updateIncognitoVisuals() {
        if (!searchBarDom) return;
        searchBarDom.classList.toggle('incognito-active', state.isIncognitoSearch);
        if (state.isIncognitoSearch) {
            searchBtn.title = '无痕模式已开启 | 右键或按 Esc+0 切换';
            // 彻底禁止浏览器原生表单记住当前搜索记录或弹出历史记录下拉框
            if (searchInput) searchInput.setAttribute('autocomplete', 'off');
        } else {
            searchBtn.title = '点击搜索 | 右键或按 Esc+0 切换无痕模式';
            // 恢复原生记录功能
            if (searchInput) searchInput.removeAttribute('autocomplete');
        }
    }
