    const dateModal = document.createElement('div');
    dateModal.className = 'modal-overlay';
    dateModal.id = 'todo-date-modal';
    dateModal.innerHTML = `
        <div class="modal-content glass-panel" style="width: 320px; padding: 25px;">
            <div class="modal-close" id="date-modal-close" title="关闭">×</div>
            <h3 id="date-modal-title" style="margin-bottom: 20px; border-left-color: var(--text-b);">设置截止时间</h3>
            <div class="input-group">
                <input type="datetime-local" id="date-modal-input" class="ui-input" style="font-size: 14px; padding: 12px; font-family: monospace; color-scheme: dark;">
            </div>
            <div style="display: flex; gap: 10px; margin-top: 20px;">
                <button class="ui-button small-btn" id="date-modal-clear" style="flex: 1; background: rgba(255,69,58,0.15); color: #ff453a; border-color: rgba(255,69,58,0.3);">清除时间</button>
                <button class="ui-button small-btn" id="date-modal-save" style="flex: 2; background: var(--text-b); color: #000; border: none; font-weight: bold;">保存设置</button>
            </div>
        </div>
    `;
    document.body.appendChild(dateModal);
    let currentSettingDateTarget = { type: null, boardId: null, itemId: null };
    document.getElementById('date-modal-close').onclick = () => dateModal.classList.remove('open');
    document.getElementById('date-modal-clear').onclick = () => { document.getElementById('date-modal-input').value = ''; };
    document.getElementById('date-modal-save').onclick = () => {
        const rawVal = document.getElementById('date-modal-input').value;
        let formattedDate = rawVal ? rawVal.replace('T', ' ') : '';
        const { type, boardId, itemId } = currentSettingDateTarget;
        const board = state.todoBoards.find(b => b.id === boardId);
        if (board) {
            if (type === 'board') { board.dueDate = formattedDate; board.notified = false; }
            else if (type === 'item') {
                const item = board.items.find(i => i.id === itemId);
                if (item) { item.dueDate = formattedDate; item.notified = false; }
            }
            saveTodoBoards(); renderTodoBoards();
        }
        dateModal.classList.remove('open');
    };
    window.openTodoDateModal = function(type, boardId, itemId, currentDate) {
        currentSettingDateTarget = { type, boardId, itemId };
        document.getElementById('date-modal-title').innerText = type === 'board' ? '设置代办表时间' : '设置项目时间';
        const inputEl = document.getElementById('date-modal-input');
        if (currentDate) { inputEl.value = currentDate.replace(' ', 'T'); }
        else { const d = new Date(); d.setMinutes(d.getMinutes() + 30); const tzOffset = d.getTimezoneOffset() * 60000; inputEl.value = new Date(d - tzOffset).toISOString().slice(0, 16); }
        dateModal.classList.add('open');
    };
    const saveMediaToDB = (id, file) => {
        return new Promise((resolve, reject) => {
            if(!db) { resolve(); return; }
            const transaction = db.transaction(['media_files'], 'readwrite');
            const store = transaction.objectStore('media_files');
            const request = store.put(file, id);
            request.onsuccess = () => resolve();
            request.onerror = (e) => reject(e);
        });
    };
    const loadMediaFromDB = (id) => {
        return new Promise((resolve, reject) => {
            if(!db) { resolve(null); return; }
            const transaction = db.transaction(['media_files'], 'readonly');
            const store = transaction.objectStore('media_files');
            const request = store.get(id);
            request.onsuccess = (e) => resolve(e.target.result);
            request.onerror = (e) => reject(e);
        });
    };
    const deleteMediaFromDB = (id) => {
        return new Promise((resolve, reject) => {
            if(!db) { resolve(); return; }
            const transaction = db.transaction(['media_files'], 'readwrite');
            const store = transaction.objectStore('media_files');
            const request = store.delete(id);
            request.onsuccess = () => resolve();
            request.onerror = (e) => reject(e);
        });
    };
