    function applySuggestionAppearance() {
        const bgFollowSwitch = document.getElementById('suggestion-bg-follow-switch');
        const bgColorPicker = document.getElementById('suggestion-bg-color');
        const bgOpacityRange = document.getElementById('range-suggestion-bg-opacity');
        const blurRange = document.getElementById('range-suggestion-blur');
        const saturateRange = document.getElementById('range-suggestion-saturate');
        const textFollowSwitch = document.getElementById('suggestion-text-follow-switch');
        const textColorPicker = document.getElementById('suggestion-text-color');
        const maxRowsRange = document.getElementById('range-suggestion-max-rows');
        const root = document.documentElement;
        if (bgFollowSwitch && bgFollowSwitch.checked) {
            root.style.removeProperty('--suggestion-bg-r');
            root.style.removeProperty('--suggestion-bg-g');
            root.style.removeProperty('--suggestion-bg-b');
        } else if (bgColorPicker) {
            const rgb = hexToRgb(bgColorPicker.value);
            root.style.setProperty('--suggestion-bg-r', rgb.r);
            root.style.setProperty('--suggestion-bg-g', rgb.g);
            root.style.setProperty('--suggestion-bg-b', rgb.b);
        }
        if (bgOpacityRange) {
            const opacity = bgOpacityRange.value / 100;
            root.style.setProperty('--suggestion-bg-opacity', opacity);
        }
        if (blurRange) {
            root.style.setProperty('--suggestion-blur', blurRange.value + 'px');
        }
        if (saturateRange) {
            root.style.setProperty('--suggestion-saturate', saturateRange.value + '%');
        }
        if (textFollowSwitch && textFollowSwitch.checked) {
            root.style.removeProperty('--suggestion-text-color');
        } else if (textColorPicker) {
            root.style.setProperty('--suggestion-text-color', textColorPicker.value);
        }
        if (maxRowsRange) {
            root.style.setProperty('--suggestion-max-rows', maxRowsRange.value);
        }
    }
