    // ==========================================
    // 🎨 折叠窗口右键颜色自定义
    // ==========================================
    const LS_SECTION_COLORS = 'section_colors';
    const colorPanel = document.getElementById('section-color-panel');
    const scpTitleLabel = document.getElementById('scp-title-label');
    const scpTitleColor = document.getElementById('scp-title-color');
    const scpBgColor = document.getElementById('scp-bg-color');
    const scpBorderColor = document.getElementById('scp-border-color');
    const scpClose = document.getElementById('scp-close');
    const scpReset = document.getElementById('scp-reset');
    const scpApplyAll = document.getElementById('scp-apply-all');
    let currentSectionKey = null;
    let currentSectionEl = null;
    let isPanelVisible = false;
    function getSectionColors() {
        try {
            return JSON.parse(localStorage.getItem(LS_SECTION_COLORS)) || {};
        } catch (e) {
            return {};
        }
    }
    function saveSectionColors(colors) {
        localStorage.setItem(LS_SECTION_COLORS, JSON.stringify(colors));
    }
    function getSectionTitle(sectionEl) {
        const titleEl = sectionEl.querySelector('.setting-title');
        if (!titleEl) return sectionEl.dataset.section || '';
        const text = titleEl.childNodes[0] ? titleEl.childNodes[0].textContent || '' : '';
        return text.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '').trim() || sectionEl.dataset.section;
    }
    function applyColorsToSection(sectionEl, colors) {
        const titleEl = sectionEl.querySelector('.setting-title');
        if (colors.title) {
            if (titleEl) titleEl.style.color = colors.title;
            sectionEl.style.setProperty('--scp-title-color', colors.title);
        }
        if (colors.bg) {
            sectionEl.style.backgroundColor = colors.bg;
        }
        if (colors.border) {
            sectionEl.style.borderColor = colors.border;
        }
    }
    function clearSectionColors(sectionEl) {
        const titleEl = sectionEl.querySelector('.setting-title');
        if (titleEl) titleEl.style.color = '';
        sectionEl.style.backgroundColor = '';
        sectionEl.style.borderColor = '';
        sectionEl.style.removeProperty('--scp-title-color');
    }
    function openPanel(sectionEl, mouseX, mouseY) {
        currentSectionEl = sectionEl;
        currentSectionKey = sectionEl.dataset.section;
        const sectionTitle = getSectionTitle(sectionEl);
        scpTitleLabel.textContent = '自定义「' + sectionTitle + '」颜色';
        const allColors = getSectionColors();
        const saved = allColors[currentSectionKey] || {};
        scpTitleColor.value = saved.title || '#a5b4fc';
        scpBgColor.value = saved.bg || '#0f172a';
        scpBorderColor.value = saved.border || '#a5b4fc';
        // Position panel near cursor, bounded to viewport
        const panelH = 220; // approximate height
        const panelW = 240;
        let left = mouseX + 8;
        let top = mouseY + 8;
        if (left + panelW > window.innerWidth - 10) left = mouseX - panelW - 8;
        if (top + panelH > window.innerHeight - 10) top = mouseY - panelH - 8;
        if (left < 0) left = 4;
        if (top < 0) top = 4;
        colorPanel.style.left = left + 'px';
        colorPanel.style.top = top + 'px';
        colorPanel.style.display = 'block';
        isPanelVisible = true;
    }
    function closePanel() {
        colorPanel.style.display = 'none';
        isPanelVisible = false;
        currentSectionKey = null;
        currentSectionEl = null;
    }
    // Delegate contextmenu to sideDrawer (contains all .setting-section)
    if (sideDrawer) {
        sideDrawer.addEventListener('contextmenu', (e) => {
            const sectionEl = e.target.closest('.setting-section');
            if (!sectionEl) return;
            e.preventDefault();
            e.stopPropagation();
            openPanel(sectionEl, e.clientX, e.clientY);
        });
    }
    // Close button
    scpClose.addEventListener('click', closePanel);
    // Click outside to close
    document.addEventListener('click', (e) => {
        if (!isPanelVisible) return;
        if (!colorPanel.contains(e.target)) {
            closePanel();
        }
    });
    // Prevent panel from capturing scroll wheel (allow background scrolling)
    colorPanel.addEventListener('wheel', (e) => {
        if (e.target === colorPanel || e.target.closest('.scp-body')) return;
    });
    // Real-time preview: input events
    scpTitleColor.addEventListener('input', () => {
        if (!currentSectionEl) return;
        const titleEl = currentSectionEl.querySelector('.setting-title');
        if (titleEl) titleEl.style.color = scpTitleColor.value;
        currentSectionEl.style.setProperty('--scp-title-color', scpTitleColor.value);
    });
    scpBgColor.addEventListener('input', () => {
        if (!currentSectionEl) return;
        currentSectionEl.style.backgroundColor = scpBgColor.value;
    });
    scpBorderColor.addEventListener('input', () => {
        if (!currentSectionEl) return;
        currentSectionEl.style.borderColor = scpBorderColor.value;
    });
    // Persist on change
    function persistCurrentColors() {
        if (!currentSectionKey) return;
        const allColors = getSectionColors();
        allColors[currentSectionKey] = {
            title: scpTitleColor.value,
            bg: scpBgColor.value,
            border: scpBorderColor.value,
        };
        saveSectionColors(allColors);
    }
    scpTitleColor.addEventListener('change', persistCurrentColors);
    scpBgColor.addEventListener('change', persistCurrentColors);
    scpBorderColor.addEventListener('change', persistCurrentColors);
    // 恢复默认
    scpReset.addEventListener('click', () => {
        if (!currentSectionKey || !currentSectionEl) return;
        const titleVal = scpTitleColor.value;
        const bgVal = scpBgColor.value;
        const borderVal = scpBorderColor.value;
        const allColors = getSectionColors();
        // 找到所有与当前颜色方案一致的窗口，一并恢复默认
        const keysToReset = [];
        for (const [key, colors] of Object.entries(allColors)) {
            if (colors.title === titleVal && colors.bg === bgVal && colors.border === borderVal) {
                keysToReset.push(key);
            }
        }
        // 清除 localStorage 记录 + 清除内联样式
        const allSections = document.querySelectorAll('.setting-section[data-section]');
        keysToReset.forEach((key) => {
            delete allColors[key];
            allSections.forEach((sec) => {
                if (sec.dataset.section === key) clearSectionColors(sec);
            });
        });
        saveSectionColors(allColors);
        // Reset pickers
        scpTitleColor.value = '#a5b4fc';
        scpBgColor.value = '#0f172a';
        scpBorderColor.value = '#a5b4fc';
    });
    // 应用到全部
    scpApplyAll.addEventListener('click', () => {
        const titleVal = scpTitleColor.value;
        const bgVal = scpBgColor.value;
        const borderVal = scpBorderColor.value;
        const allSections = document.querySelectorAll('.setting-section[data-section]');
        const allColors = getSectionColors();
        allSections.forEach((sec) => {
            const key = sec.dataset.section;
            applyColorsToSection(sec, { title: titleVal, bg: bgVal, border: borderVal });
            allColors[key] = { title: titleVal, bg: bgVal, border: borderVal };
        });
        saveSectionColors(allColors);
    });
    // 页面加载恢复所有自定义颜色
    (function restoreAllSectionColors() {
        const allColors = getSectionColors();
        const sections = document.querySelectorAll('.setting-section[data-section]');
        sections.forEach((sec) => {
            const key = sec.dataset.section;
            if (allColors[key]) {
                applyColorsToSection(sec, allColors[key]);
            }
        });
    })();
    // ============== BinixOvO 插件弹窗 — 完整交互逻辑 ==============
