    function amapWindPowerToKmph(power) {
        if (!power || power === '≤3') return 12;
        var num = parseInt(power) || 3;
        if (num <= 1) return 5;
        if (num === 2) return 11;
        if (num === 3) return 19;
        if (num === 4) return 28;
        if (num === 5) return 38;
        if (num === 6) return 49;
        if (num >= 7) return 61;
        return 19;
    }
    function convertAmapWeatherToWttr(amapData, city, lat, lon) {
        var forecast = amapData.forecasts[0];
        var casts = forecast.casts || [];
        var firstDay = casts[0] || {};
        var now = new Date();
        var month = String(now.getMonth() + 1).padStart(2, '0');
        var day = String(now.getDate()).padStart(2, '0');
        var todayStr = now.getFullYear() + '-' + month + '-' + day;
        var data = {
            current_condition: [{
                temp_C: String(firstDay.daytemp || '--'),
                humidity: '--',
                FeelsLikeC: String(firstDay.daytemp || '--'),
                weatherCode: '116',
                windspeedKmph: String(amapWindPowerToKmph(firstDay.daypower)),
                winddir16Point: firstDay.daywind || '--',
                pressure: '--',
                uvIndex: '--',
                weatherDesc: [{ value: firstDay.dayweather || '晴' }],
                weatherIconUrl: [{ value: '' }]
            }],
            weather: [],
            nearest_area: [{
                areaName: [{ value: city || forecast.city || '当前位置' }],
                latitude: String(lat),
                longitude: String(lon)
            }]
        };
        var maxDays = Math.min(casts.length, 3);
        for (var i = 0; i < maxDays; i++) {
            var c = casts[i];
            data.weather.push({
                date: c.date || todayStr,
                maxtempC: String(c.daytemp || '--'),
                mintempC: String(c.nighttemp || '--'),
                avgtempC: String(Math.round((parseInt(c.daytemp) + parseInt(c.nighttemp)) / 2)),
                astronomy: [{ sunrise: '06:00 AM', sunset: '06:00 PM', moonrise: '', moonset: '', moon_illumination: '', moon_phase: '' }],
                hourly: [{
                    time: '1200',
                    tempC: String(c.daytemp || '--'),
                    windspeedKmph: String(amapWindPowerToKmph(c.daypower)),
                    winddir16Point: c.daywind || '--',
                    weatherIconUrl: [{ value: '' }],
                    weatherDesc: [{ value: c.dayweather || '晴' }],
                    chanceofrain: '0'
                }]
            });
        }
        return data;
    }
