    function getApiConfigList() {
        try {
            var raw = localStorage.getItem('binixovo_api_config');
            if (raw) {
                var parsed = JSON.parse(raw);
                if (Array.isArray(parsed) && parsed.length > 0) return parsed;
            }
        } catch(e) {}
        return JSON.parse(JSON.stringify(API_UI_DEFAULTS));
    }
    function saveApiConfigList(list) {
        try {
            localStorage.setItem('binixovo_api_config', JSON.stringify(list));
            if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
                chrome.storage.local.set({ binixovo_api_config: list }, function() {});
            }
            // 重置缓存，让下次 getApi 重新加载
            __apiConfigCache = null;
            loadApiConfig();
        } catch(e) {}
    }
    function getApiById(id) {
        var list = getApiConfigList();
        for (var i = 0; i < list.length; i++) {
            if (list[i].id === id) return list[i];
        }
        return null;
    }
    function getApiUrl(id, replacements) {
        var api = getApiById(id);
        if (!api || !api.enabled) {
            api = getApiById(id); // fallback: try anyway
        }
        if (!api) return '';
        var url = api.url;
        if (replacements) {
            for (var k in replacements) {
                if (replacements.hasOwnProperty(k)) {
                    url = url.replace('{' + k + '}', encodeURIComponent(replacements[k]));
                }
            }
        }
        return url;
    }
    // 暴露全局 API 函数
    window.getApi = function(key) {
        var shortKey = key.replace(/^api_/, '');
        var api = getApiById('api_' + shortKey) || getApiById(key);
        if (api && api.enabled) return { url: api.url, key: api.key || '' };
        // 回退到原有 API_DEFAULTS
        loadApiConfig();
        return API_DEFAULTS[key] || { url: '', key: '' };
    };
    window.getApiUrl = getApiUrl;
    window.getApiConfigList = getApiConfigList;
    window.saveApiConfigList = saveApiConfigList;
    // ==========================================
