    var apiEditorCallback = null;
    function renderApiConfigList() {
        var container = document.getElementById('api-config-list');
        if (!container) return;
        var list = getApiConfigList();
        var html = '';
        for (var i = 0; i < list.length; i++) {
            var api = list[i];
            var disabledClass = api.enabled ? '' : ' disabled';
            var statusClass = api.enabled ? 'enabled' : 'disabled';
            html += '<div class="api-config-item' + disabledClass + '" data-api-id="' + escapeHTML(api.id) + '" data-index="' + i + '">';
            html += '<div class="api-config-item-header">';
            html += '<span class="api-status-dot ' + statusClass + '"></span>';
            html += '<span class="api-name" title="' + escapeHTML(api.name) + '">' + escapeHTML(api.name) + '</span>';
            html += '<span class="api-type-tag">' + escapeHTML(api.type) + '</span>';
            html += '<span class="api-expand-arrow">&#9660;</span>';
            html += '</div>';
            html += '<div class="api-config-item-body">';
            html += '<div class="api-detail-row"><span class="api-detail-label">URL</span><span class="api-detail-value" title="' + escapeHTML(api.url) + '">' + escapeHTML(api.url) + '</span></div>';
            if (api.key) {
                html += '<div class="api-detail-row"><span class="api-detail-label">Key</span><span class="api-detail-value">' + escapeHTML(api.key) + '</span></div>';
            }
            html += '<div class="api-detail-row"><span class="api-detail-label">ID</span><span class="api-detail-value">' + escapeHTML(api.id) + '</span></div>';
            html += '<div class="api-config-item-actions">';
            html += '<button class="edit-btn" data-action="edit" data-api-id="' + escapeHTML(api.id) + '">编辑</button>';
            html += '<button class="delete-btn" data-action="delete" data-api-id="' + escapeHTML(api.id) + '">删除</button>';
            html += '</div>';
            html += '</div>';
            html += '</div>';
        }
        container.innerHTML = html;
        // 绑定点击事件：展开/折叠
        var items = container.querySelectorAll('.api-config-item');
        for (var j = 0; j < items.length; j++) {
            (function(item) {
                item.querySelector('.api-config-item-header').addEventListener('click', function(e) {
                    if (e.target.closest('button')) return;
                    item.classList.toggle('expanded');
                });
                // 编辑按钮
                var editBtn = item.querySelector('.edit-btn');
                if (editBtn) {
                    editBtn.addEventListener('click', function(e) {
                        e.stopPropagation();
                        var apiId = editBtn.getAttribute('data-api-id');
                        var api = getApiById(apiId);
                        if (api) openApiEditor(api);
                    });
                }
                // 删除按钮
                var deleteBtn = item.querySelector('.delete-btn');
                if (deleteBtn) {
                    deleteBtn.addEventListener('click', function(e) {
                        e.stopPropagation();
                        var apiId = deleteBtn.getAttribute('data-api-id');
                        var api = getApiById(apiId);
                        if (api && confirm('确定要删除 "' + api.name + '" 吗？此操作不可撤销。')) {
                            deleteApiConfig(apiId);
                        }
                    });
                }
            })(items[j]);
        }
    }
    function deleteApiConfig(id) {
        var list = getApiConfigList();
        var newList = [];
        for (var i = 0; i < list.length; i++) {
            if (list[i].id !== id) newList.push(list[i]);
        }
        saveApiConfigList(newList);
        renderApiConfigList();
    }
    function openApiEditor(api) {
        var overlay = document.getElementById('api-editor-overlay');
        if (!overlay) return;
        document.getElementById('api-editor-title').textContent = api ? '编辑 API' : '添加 API';
        document.getElementById('api-editor-name').value = api ? api.name : '';
        document.getElementById('api-editor-type').value = api ? api.type : '自定义';
        document.getElementById('api-editor-url').value = api ? api.url : '';
        document.getElementById('api-editor-key').value = api ? (api.key || '') : '';
        document.getElementById('api-editor-internal-key').value = api ? api.id : '';
        document.getElementById('api-editor-enabled').checked = api ? api.enabled : true;
        apiEditorCallback = api ? api.id : null;
        overlay.style.display = 'flex';
    }
    function closeApiEditor() {
        var overlay = document.getElementById('api-editor-overlay');
        if (overlay) overlay.style.display = 'none';
        apiEditorCallback = null;
    }
    function saveApiEditor() {
        var name = document.getElementById('api-editor-name').value.trim();
        var type = document.getElementById('api-editor-type').value;
        var url = document.getElementById('api-editor-url').value.trim();
        var key = document.getElementById('api-editor-key').value.trim();
        var internalKey = document.getElementById('api-editor-internal-key').value.trim();
        var enabled = document.getElementById('api-editor-enabled').checked;
        if (!name) { alert('请输入名称'); return; }
        if (!url) { alert('请输入 URL'); return; }
        if (!internalKey) { alert('请输入内部 Key（唯一标识）'); return; }
        var list = getApiConfigList();
        var existingId = apiEditorCallback;
        if (existingId) {
            // 编辑现有 API
            for (var i = 0; i < list.length; i++) {
                if (list[i].id === existingId) {
                    // 如果 ID 改变了，检查新 ID 是否冲突
                    if (internalKey !== existingId) {
                        for (var j = 0; j < list.length; j++) {
                            if (list[j].id === internalKey) { alert('内部 Key "' + internalKey + '" 已存在'); return; }
                        }
                    }
                    list[i].name = name;
                    list[i].type = type;
                    list[i].url = url;
                    list[i].key = key;
                    list[i].enabled = enabled;
                    list[i].id = internalKey;
                    break;
                }
            }
        } else {
            // 添加新 API
            for (var k = 0; k < list.length; k++) {
                if (list[k].id === internalKey) { alert('内部 Key "' + internalKey + '" 已存在'); return; }
            }
            list.push({
                id: internalKey,
                name: name,
                type: type,
                url: url,
                key: key,
                enabled: enabled
            });
        }
        saveApiConfigList(list);
        closeApiEditor();
        renderApiConfigList();
    }
    // ==========================================
    // 初始化 API 配置 UI
    // ==========================================
    (function initApiConfigUI() {
        renderApiConfigList();
        var addBtn = document.getElementById('add-api-btn');
        if (addBtn) {
            addBtn.addEventListener('click', function() { openApiEditor(null); });
        }
        var saveBtn = document.getElementById('api-editor-save');
        if (saveBtn) {
            saveBtn.addEventListener('click', saveApiEditor);
        }
        var cancelBtn = document.getElementById('api-editor-cancel');
        if (cancelBtn) {
            cancelBtn.addEventListener('click', closeApiEditor);
        }
        var closeBtn = document.getElementById('api-editor-close');
        if (closeBtn) {
            closeBtn.addEventListener('click', closeApiEditor);
        }
        // 点击遮罩关闭
        var overlay = document.getElementById('api-editor-overlay');
        if (overlay) {
            overlay.addEventListener('click', function(e) {
                if (e.target === overlay) closeApiEditor();
            });
        }
        // ESC 关闭
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && document.getElementById('api-editor-overlay').style.display === 'flex') {
                closeApiEditor();
            }
        });
    })();
    // ==========================================
    // 🖼️ 统一壁纸库 (收藏 + 历史)
