    ctx.save();
    ctx.beginPath();
    ctx.rect(pad.left, pad.top, chartW, priceH);
    ctx.clip();
    ctx.beginPath();
    for (var i = 0; i < viewData.length; i++) {
        var x = pad.left + stepX * i;
        var y = pad.top + priceH - ((viewData[i].price - minPrice) / priceRange) * priceH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
