// 绘制K线图
function drawKlineChart(canvas, data, mas, viewRange) {
    if (!canvas || !data || data.length === 0) return;
    mas = ensureStockMAs(data, mas);
    var ctx = canvas.getContext('2d');
    var W = canvas.width;
    var H = canvas.height;
    var pad = { top: 10, right: 10, bottom: 45, left: 55 };
    var chartW = W - pad.left - pad.right;
    var chartH = H - pad.top - pad.bottom;
    var scrubberH = 28;
    var mainH = chartH - scrubberH - 4;
    var volH = Math.floor(mainH * 0.22);
    var klineH = mainH - volH - 5;
    // View range
    var vStart = 0, vEnd = data.length - 1;
    if (viewRange) {
        vStart = Number.isFinite(Number(viewRange.start)) ? Math.max(0, Math.min(data.length - 1, Number(viewRange.start))) : 0;
        vEnd = Number.isFinite(Number(viewRange.end)) ? Math.max(0, Math.min(data.length - 1, Number(viewRange.end))) : data.length - 1;
        if (vStart > vEnd) { var t = vStart; vStart = vEnd; vEnd = t; }
    }
    var visibleData = data.slice(vStart, vEnd + 1);
    if (!visibleData.length) visibleData = data.slice();
    var visibleLen = visibleData.length;
    // Store scrubber state
    canvas._scrubber = {
        fullData: data, viewStart: vStart, viewEnd: vEnd,
        scrubY: pad.top + mainH + 4, scrubberH: scrubberH,
        padLeft: pad.left, chartW: chartW, mas: mas
    };
    ctx.fillStyle = '#1A1A1E';
    ctx.fillRect(0, 0, W, H);
    // Price range
    var minPrice = Infinity, maxPrice = -Infinity;
    var maxVol = 0;
    for (var i = 0; i < visibleLen; i++) {
        if (visibleData[i].low < minPrice) minPrice = visibleData[i].low;
        if (visibleData[i].high > maxPrice) maxPrice = visibleData[i].high;
        if (visibleData[i].volume > maxVol) maxVol = visibleData[i].volume;
    }
    for (var m = 0; m < mas.length; m++) {
        for (var i = vStart; i <= vEnd; i++) {
            if (mas[m][i] != null) {
                if (mas[m][i] < minPrice) minPrice = mas[m][i];
                if (mas[m][i] > maxPrice) maxPrice = mas[m][i];
            }
        }
    }
    var priceRange = maxPrice - minPrice || 1;
    minPrice -= priceRange * 0.03;
    maxPrice += priceRange * 0.03;
    priceRange = maxPrice - minPrice;
    // Grid
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 0.5;
    for (var g = 0; g <= 4; g++) {
        var gy = pad.top + (klineH / 4) * g;
        ctx.beginPath();
        ctx.moveTo(pad.left, gy);
        ctx.lineTo(W - pad.right, gy);
        ctx.stroke();
    }
    // Price labels
    ctx.fillStyle = '#888888';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    for (var p = 0; p <= 4; p++) {
        var price = maxPrice - (priceRange / 4) * p;
        var py = pad.top + (klineH / 4) * p;
        ctx.fillText(price.toFixed(2), pad.left - 5, py + 4);
    }
    // K-line candles
    var gap = chartW / visibleLen;
    var candleW = Math.max(1, gap * 0.7);
    for (var i = 0; i < visibleLen; i++) {
        var d = visibleData[i];
        var cx = pad.left + gap * i + gap / 2;
        var isUp = d.close >= d.open;
        var highY = pad.top + klineH - ((d.high - minPrice) / priceRange) * klineH;
        var lowY = pad.top + klineH - ((d.low - minPrice) / priceRange) * klineH;
        var openY = pad.top + klineH - ((d.open - minPrice) / priceRange) * klineH;
        var closeY = pad.top + klineH - ((d.close - minPrice) / priceRange) * klineH;
        var color = isUp ? '#FF3B30' : '#30D158';
        // Wick
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(cx, highY);
        ctx.lineTo(cx, lowY);
        ctx.stroke();
        // Body
        var bodyTop = Math.min(openY, closeY);
        var bodyH = Math.max(1, Math.abs(closeY - openY));
        ctx.fillStyle = isUp ? '#FF3B30' : 'transparent';
        ctx.fillRect(cx - candleW / 2, bodyTop, candleW, bodyH);
        if (!isUp) {
            ctx.strokeStyle = '#30D158';
            ctx.strokeRect(cx - candleW / 2, bodyTop, candleW, bodyH);
        }
    }
    // MA lines
    var maColors = ['#2196f3', '#ff9800', '#9c27b0'];
    var maLabels = ['MA5', 'MA10', 'MA20'];
    for (var m = 0; m < mas.length; m++) {
        var ma = mas[m];
        ctx.strokeStyle = maColors[m];
        ctx.lineWidth = 1;
        ctx.beginPath();
        var started = false;
        var lastX = 0, lastY = 0;
        for (var i = 0; i < visibleLen; i++) {
            var dataIdx = vStart + i;
            if (ma[dataIdx] == null) continue;
            var mx = pad.left + gap * i + gap / 2;
            var my = pad.top + klineH - ((ma[dataIdx] - minPrice) / priceRange) * klineH;
            if (!started) { ctx.moveTo(mx, my); started = true; }
            else ctx.lineTo(mx, my);
            lastX = mx;
            lastY = my;
        }
        ctx.stroke();
        if (started) {
            ctx.fillStyle = maColors[m];
            ctx.font = '9px sans-serif';
            ctx.textAlign = 'left';
            ctx.fillText(maLabels[m], lastX + 2, lastY - 2);
        }
    }
    // Volume bars
    var volStartY = pad.top + klineH + 5;
    for (var i = 0; i < visibleLen; i++) {
        var d = visibleData[i];
        var vx = pad.left + gap * i + gap / 2;
        var barW = Math.max(1, gap * 0.7);
        var barH = maxVol > 0 ? (d.volume / maxVol) * volH : 0;
        var vUp = d.close >= d.open;
        ctx.fillStyle = vUp ? 'rgba(255,59,48,0.5)' : 'rgba(48,209,88,0.5)';
        ctx.fillRect(vx - barW / 2, volStartY + volH - barH, barW, barH);
    }
    // Date labels
    ctx.fillStyle = '#888888';
    ctx.font = '9px sans-serif';
    ctx.textAlign = 'center';
    var lCount = Math.min(5, visibleLen);
    for (var t = 0; t < lCount; t++) {
        var lIdx = Math.floor(visibleLen * t / Math.max(1, lCount - 1));
        if (lIdx >= visibleLen) lIdx = visibleLen - 1;
        var lx = pad.left + gap * lIdx + gap / 2;
        var dateStr = visibleData[lIdx].date;
        var shortDate = dateStr.length > 5 ? dateStr.substring(5) : dateStr;
        ctx.fillText(shortDate, lx, H - 10);
    }
    // === Bottom Scrubber ===
    var scrubY = pad.top + mainH + 4;
    var scrubMidY = scrubY + scrubberH / 2;
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.fillRect(pad.left, scrubY, chartW, scrubberH);
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 0.5;
    ctx.strokeRect(pad.left, scrubY, chartW, scrubberH);
    // Mini close-price line (full data)
    var miniStepX = data.length > 1 ? chartW / (data.length - 1) : 0;
    var fmin = Infinity, fmax = -Infinity;
    for (var i = 0; i < data.length; i++) {
        if (data[i].close < fmin) fmin = data[i].close;
        if (data[i].close > fmax) fmax = data[i].close;
    }
    var frange = fmax - fmin || 1;
    fmin -= frange * 0.05;
    fmax += frange * 0.05;
    frange = fmax - fmin;
    ctx.strokeStyle = 'rgba(255,255,255,0.25)';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    for (var i = 0; i < data.length; i++) {
        var mx = pad.left + miniStepX * i;
        var my = scrubY + scrubberH - ((data[i].close - fmin) / frange) * scrubberH;
        if (i === 0) ctx.moveTo(mx, my);
        else ctx.lineTo(mx, my);
    }
    ctx.stroke();
    // Selection highlight
    var selLeft  = pad.left + (vStart / Math.max(1, data.length - 1)) * chartW;
    var selRight = pad.left + (vEnd   / Math.max(1, data.length - 1)) * chartW;
    ctx.fillStyle = 'rgba(59,130,246,0.18)';
    ctx.fillRect(selLeft, scrubY, selRight - selLeft, scrubberH);
    ctx.strokeStyle = 'rgba(59,130,246,0.55)';
    ctx.lineWidth = 1;
    ctx.strokeRect(selLeft, scrubY, selRight - selLeft, scrubberH);
    // Handles
    var hr = 5;
    ctx.fillStyle = '#3B82F6';
    ctx.beginPath(); ctx.arc(selLeft, scrubMidY, hr, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(selRight, scrubMidY, hr, 0, Math.PI * 2); ctx.fill();
}
