function renderStockWidget(bodyEl, item) {
    item.data = item.data || {};
    if (stockState.watchlist.length === 0) {
        loadStockWatchlist();
    }
    var refreshTimer = null;
    function getSizes() {
        var tile = bodyEl.parentElement;
        var w = tile ? tile.offsetWidth : 200;
        var h = tile ? tile.offsetHeight : 150;
        var minDim = Math.min(w, h);
        var nameFS, changeFS, pad, rowPad;
        if (minDim < 100) {
            nameFS = 9; changeFS = 8; pad = 3; rowPad = 2;
        } else if (minDim < 160) {
            nameFS = 11; changeFS = 10; pad = 5; rowPad = 4;
        } else if (minDim < 280) {
            nameFS = 13; changeFS = 11; pad = 8; rowPad = 5;
        } else {
            nameFS = 15; changeFS = 13; pad = 12; rowPad = 8;
        }
        return { nameFS: nameFS, changeFS: changeFS, pad: pad, rowPad: rowPad };
    }
    function render() {
        var sz = getSizes();
        var stocks = stockState.watchlist;
        var rowsHTML = '';
        // Color palette - Chinese convention: red up, green down
        var greenColor = '#30D158';
        var redColor = '#FF3B30';
        for (var i = 0; i < stocks.length; i++) {
            var s = stocks[i];
            var changeColor = (s.changePct || 0) >= 0 ? redColor : greenColor;
            var changeSign = (s.changePct || 0) >= 0 ? '+' : '';
            var changeStr = s._dataReady ? changeSign + (s.changePct || 0).toFixed(2) + '%' : '--';
            rowsHTML +=
                '<div class="stock-widget-row" style="display:flex;align-items:center;justify-content:space-between;padding:' + sz.rowPad + 'px 0;border-bottom:1px solid rgba(255,255,255,0.06);cursor:pointer;gap:4px;">' +
                    '<span style="flex:1;min-width:0;font-size:' + sz.nameFS + 'px;color:#ffffff;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHTML(s.name) + '</span>' +
                    '<span style="flex-shrink:0;font-size:' + sz.changeFS + 'px;color:' + changeColor + ';font-weight:500;white-space:nowrap;">' + changeStr + '</span>' +
                '</div>';
        }
        // Body element fills entire card — background + border-radius on bodyEl itself
        bodyEl.style.margin = '0';
        bodyEl.style.padding = '0';
        bodyEl.style.width = '100%';
        bodyEl.style.height = '100%';
        bodyEl.style.boxSizing = 'border-box';
        bodyEl.style.background = '#202020';
        bodyEl.style.borderRadius = '8px';
        bodyEl.style.overflow = 'hidden';
        bodyEl.innerHTML =
            '<div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;padding:' + sz.pad + 'px;">' +
                '<div class="stock-widget-scroll" style="flex:1;min-height:0;">' + rowsHTML + '</div>' +
                '<div style="text-align:center;margin-top:4px;font-size:9px;color:rgba(255,255,255,0.3);flex-shrink:0;">' +
                    stocks.length + ' 只自选 · ' + (stockState.isLoadingQuotes ? '刷新中...' : '30s自动刷新') +
                '</div>' +
            '</div>';
        var rows = bodyEl.querySelectorAll('.stock-widget-row');
        rows.forEach(function(row, idx) {
            row.addEventListener('click', function(e) {
                e.stopPropagation();
                openStockModal(idx);
            });
            row.addEventListener('mouseenter', function() {
                this.style.background = 'rgba(255,255,255,0.05)';
            });
            row.addEventListener('mouseleave', function() {
                this.style.background = '';
            });
        });
        bodyEl.onclick = function(e) {
            if (!e.target.closest('.stock-widget-row')) {
                openStockModal(-1);
            }
        };
    }
    render();
    async function refreshData() {
        await updateStockQuotes();
        if (bodyEl.parentElement) {
            render();
        }
    }
    refreshData();
    refreshTimer = setInterval(refreshData, 30000);
    return function cleanup() {
        if (refreshTimer) clearInterval(refreshTimer);
    };
}
