    var ringOffset = ringCirc * (1 - ratio);
    var arcColor = isComplete ? '#10B981' : '#6366F1';
    var glowColor = isComplete ? 'rgba(16,185,129,0.4)' : 'rgba(99,102,241,0.4)';
