    var overlay = document.createElement('div');
    overlay.className = 'habit-settings-overlay';
    overlay.style.cssText = 'position:fixed; inset:0; z-index:10000; display:flex; align-items:center; justify-content:center; pointer-events:none;';
    var backdrop = document.createElement('div');
    backdrop.className = 'habit-settings-backdrop';
    backdrop.style.cssText = 'position:absolute; inset:0; background:linear-gradient(135deg, #0A0E27 0%, #0F172A 100%); opacity:0.92; animation:habitOverlayIn 0.35s ease; pointer-events:auto;';
    var card = document.createElement('div');
    card.className = 'habit-settings-card';
    card.style.cssText = 'background:#121212; border-radius:16px; padding:32px 28px; width:380px; max-width:min(480px,92vw); max-height:90vh; overflow-y:auto; box-shadow:0 16px 48px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,255,255,0.04); position:relative; z-index:1; pointer-events:auto; animation:habitCardIn 0.4s cubic-bezier(0.16,1,0.3,1);';
