    document.body.appendChild(overlay);
    // --- 事件绑定 ---
    var svgArc = card.querySelector('.habit-preview-arc');
    var previewNum = card.querySelector('.habit-preview-num');
    var previewName = card.querySelector('.habit-preview-name');
    var nameInput = card.querySelector('.habit-name-input');
    var targetVal = card.querySelector('.habit-target-val');
    var compVal = card.querySelector('.habit-comp-val');
