    var closeBtn = card.querySelector('.habit-settings-close');
    closeBtn.onclick = closeModal;
    closeBtn.onkeydown = function(e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); closeModal(); } };
    // 目标步进器
    card.querySelector('.habit-target-dec').onclick = function () {
        if (currentTarget > 1) { currentTarget--; targetVal.textContent = currentTarget; updatePreview(); }
    };
    card.querySelector('.habit-target-inc').onclick = function () {
        if (currentTarget < 999) { currentTarget++; targetVal.textContent = currentTarget; updatePreview(); }
    };
    // 已完成步进器
    card.querySelector('.habit-comp-dec').onclick = function () {
        if (currentComp > 0) { currentComp--; compVal.textContent = currentComp; updatePreview(); }
    };
    card.querySelector('.habit-comp-inc').onclick = function () {
        if (currentComp < currentTarget) { currentComp++; compVal.textContent = currentComp; updatePreview(); }
    };
    // 每天重置 pill 开关
    var radioYes = card.querySelector('.habit-radio-yes');
    var radioNo = card.querySelector('.habit-radio-no');
    function setResetDaily(val) {
        currentReset = val;
        if (val) {
            radioYes.style.background = '#6366F1'; radioYes.style.color = '#FFFFFF'; radioYes.style.fontWeight = '600';
            radioYes.setAttribute('aria-checked', 'true');
            radioNo.style.background = 'transparent'; radioNo.style.color = '#94A3B8'; radioNo.style.fontWeight = '400';
            radioNo.setAttribute('aria-checked', 'false');
        } else {
            radioNo.style.background = '#6366F1'; radioNo.style.color = '#FFFFFF'; radioNo.style.fontWeight = '600';
            radioNo.setAttribute('aria-checked', 'true');
            radioYes.style.background = 'transparent'; radioYes.style.color = '#94A3B8'; radioYes.style.fontWeight = '400';
            radioYes.setAttribute('aria-checked', 'false');
        }
    }
    radioYes.onclick = function () { setResetDaily(true); };
    radioYes.onkeydown = function(e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setResetDaily(true); } };
    radioNo.onclick = function () { setResetDaily(false); };
    radioNo.onkeydown = function(e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setResetDaily(false); } };
    // 名称输入实时更新预览 + 空状态切换
    nameInput.oninput = function () {
        var val = this.value || '';
        previewName.textContent = val || '未设置';
        if (emptyGuide) {
            emptyGuide.style.display = val ? 'none' : '';
        }
    };
    // 保存按钮
    card.querySelector('.habit-save-btn').onclick = function () {
        var newName = nameInput.value.trim();
        if (!newName) { nameInput.style.borderColor = '#EF4444'; nameInput.style.boxShadow = '0 0 0 3px rgba(239,68,68,0.15)'; nameInput.focus(); return; }
        item.data.name = newName;
        item.data.target = currentTarget;
        item.data.completed = currentComp;
        item.data.resetDaily = currentReset;
        if (currentReset) {
            var d = new Date();
            item.data.lastResetDate = d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate();
        } else {
            item.data.lastResetDate = '';
        }
        window.saveData();
        overlay.remove();
        renderFn(true);
    };
    // 点击遮罩关闭
    backdrop.addEventListener('click', function (e) {
        if (e.target === backdrop) closeModal();
    });
