        modal.addEventListener('click', function(e) { if (e.target === modal) closeFoodModal(); });
        var panel = document.createElement('div');
        panel.style.cssText = 'background:rgba(24,24,36,0.95);border-radius:20px;padding:28px 32px;width:min(600px,90vw);max-height:85vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,0.5);border:1px solid rgba(255,255,255,0.1);';
        panel.addEventListener('click', function(e) { e.stopPropagation(); });
