            '<button id="food-delete-selected-btn" style="padding:5px 14px;border-radius:10px;border:1px solid rgba(255,69,58,0.3);background:rgba(255,69,58,0.15);color:#ff453a;font-size:13px;cursor:pointer;">删除选中</button>' +
            '<span id="food-selected-count" style="font-size:12px;color:#888;"></span>' +
            '<button id="food-batch-cancel-btn" style="margin-left:auto;padding:5px 14px;border-radius:10px;border:1px solid rgba(255,255,255,0.12);background:transparent;color:#aaa;font-size:13px;cursor:pointer;">取消</button>';
        manageArea.appendChild(batchBar);
        // 食物网格
        var gridWrap = document.createElement('div');
        gridWrap.style.cssText = 'flex:1;overflow-y:auto;min-height:0;';
