        // ========== 历史面板 ==========
        var historyArea = document.createElement('div');
        historyArea.id = 'food-history-area';
        historyArea.style.cssText = 'flex:1;display:none;flex-direction:column;min-height:0;';
        var historyHeader = document.createElement('div');
        historyHeader.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-shrink:0;';
        historyHeader.innerHTML = '<span style="color:#aaa;font-size:13px;">最近 ' + Math.min(item.data.foodHistory.length, MAX_HISTORY) + ' 条记录</span>' +
            '<button id="food-clear-history-btn" style="padding:4px 12px;border-radius:8px;border:1px solid rgba(255,69,58,0.3);background:transparent;color:#ff453a;font-size:12px;cursor:pointer;">清空历史</button>';
        historyArea.appendChild(historyHeader);
